window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U3"]={"deck":"U3","slides":[{"p":1,"title":"3강 표지: 빈 분리파와 근대건축의 태동","terms":["Wiener Secession"],"pass1":[{"kind":"say","lines":["3강이 시작돼요. 제목은 '빈 분리파와 근대건축의 태동'이에요.","무대는 오스트리아 빈이고, 주인공은 세 팀이에요.","**빈 분리파(Wiener Secession)**, 오토 바그너, 아돌프 로스예요."]},{"kind":"say","lines":["주문을 한 번 외워요. 기계 시대에 건축은 어떻게 생겨야 하나?","싫어 → 새 장식 → 정리 → 없애.","3강은 이 중에서 '정리'와 '없애' 단계예요."]}],"pass2":[],"pass3":[]},{"p":2,"title":"근대건축의 태동: 19세기 말 빈의 도시적 상황","terms":["링 슈트라세","Imperial style","역사주의"],"pass1":[{"kind":"say","lines":["빈은 황제가 다스리던 아주 보수적인 도시였어요.","옛날 양식을 좋아했는데, 도시를 새로 꾸미면서 분위기가 바뀌어요.","그 무대가 **링 슈트라세**라는 둥근 큰길이에요."]},{"kind":"analogy","head":"황제의 도시 빈","scene":"왕궁 둘레의 낡은 성벽을 허물고 큰 순환 도로를 냈어요.","map":[["성벽을 허문 자리","**링 슈트라세**라는 둥근 큰길"],["길가에 세운 건물","신흥 중산계층을 위한 부르주아 아파트"],["남아 있던 취향","옛 양식을 되풀이하는 **역사주의**"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**임페리얼 스타일(Imperial style)**: 황제 왕정 문화가 선호한 전통 양식이에요.","르네상스 양식, 바로크 양식과 함께 묶여서 언급돼요.","**역사주의**: 과거의 고전적 형상에서 영감을 얻으려는 태도예요.","**링 슈트라세**: 쇼르스케가 '일종의 문화적 선언'이라 정의한 빈의 도시 미화 사업이에요."]},{"kind":"points","head":"시험에 나오는 문장 그대로","items":["빈은 국가 주도의 관료주의적 보수 성향이 매우 강했어요.","황제 집권시의 왕정 문화가 지배적이어서 르네상스, 바로크, **임페리얼 스타일(Imperial style)**을 선호했어요.","**링 슈트라세**의 가장 큰 목적은 '도시 이미지의 미화'였어요.","신흥 중산계층을 위한 다수의 부르주아 아파트들이 건설되기 시작했어요.","이 상황이 **역사주의**를 넘어 근대적 도시와 근대적 양식의 탄생을 알리는 계기가 되었어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"배경 지식","lines":["쇼르스케는 19세기 말 빈 문화를 연구한 역사학자예요.","슬라이드에는 '쇼르스케는 일종의 문화적 선언이라 정의했다'만 나와요.","시험에는 '링 슈트라세를 문화적 선언이라 부른 사람은?' 으로 나와요."]}],"pass3":[{"kind":"check","q":"**링 슈트라세** 건설의 가장 큰 목적은 무엇이었을까요?","choices":["산업 생산 증대","도시 이미지의 미화","군사 방어"],"a":1,"why":"쇼르스케는 문화적 선언이라 했고, 목적은 '도시 이미지의 미화'였어요."},{"kind":"check","q":"19세기 말 빈이 선호한 양식이 아닌 것은?","choices":["르네상스 양식","바로크 양식","**임페리얼 스타일(Imperial style)**","고딕 부활 양식"],"a":3,"why":"슬라이드는 르네상스, 바로크, 임페리얼 스타일 세 가지만 말해요."},{"kind":"english","head":"논술 답안: 19세기 말 빈의 도시적 상황","en":"빈은 국가 주도의 관료주의적 보수 성향이 강하고 황제의 왕정 문화가 지배적이어서 르네상스, 바로크, 임페리얼 스타일을 선호하였다.","ko":"링 슈트라세는 쇼르스케가 문화적 선언이라 정의한 도시 미화 사업이며, 부르주아 아파트가 들어서면서 역사주의를 넘어선 근대 양식의 과제가 생겼다.","tip":"'보수 + 링 슈트라세 + 부르주아 아파트 + 새 양식 과제' 네 덩어리로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.25,0.07],"c":[0.0375,0.03,0.275,0.11],"r":3.3333,"img":"img/U3/walk/p002_22_01.jpg","say":"제목이 '근대건축의 태동'이에요. 3강 전체의 배경 설명이에요."},{"b":[0.08,0.19,0.87,0.16],"c":[0.0365,0.1733,0.957,0.1933],"r":6.6011,"img":"img/U3/walk/p002_22_02.jpg","say":"첫 항목. 관료주의적 보수 성향, 왕정 문화, 임페리얼 스타일 선호."},{"b":[0.08,0.36,0.87,0.11],"c":[0.0365,0.3183,0.957,0.1933],"r":6.6011,"img":"img/U3/walk/p002_22_03.jpg","say":"둘째 항목. 링 슈트라세와 쇼르스케의 '문화적 선언', 도시 이미지의 미화."},{"b":[0.08,0.48,0.87,0.06],"c":[0.0365,0.4133,0.957,0.1933],"r":6.6011,"img":"img/U3/walk/p002_22_04.jpg","say":"셋째 항목. 신흥 중산계층을 위한 부르주아 아파트."},{"b":[0.08,0.55,0.87,0.11],"c":[0.0365,0.5083,0.957,0.1933],"r":6.6011,"img":"img/U3/walk/p002_22_05.jpg","say":"넷째 항목. 역사주의를 넘어 근대적 도시와 근대적 양식의 탄생."},{"b":[0.08,0.66,0.87,0.06],"c":[0.0365,0.5933,0.957,0.1933],"r":6.6011,"img":"img/U3/walk/p002_22_06.jpg","say":"다섯째 항목. 건축가들은 새 양식을 정립해야 하는 과제를 안게 됐어요."}]}},{"p":3,"title":"총체예술(Gesamtkunstwerk)과 요제프 호프만, 푸커스도르프 요양원 1905","terms":["Total Art","요제프 호프만","푸커스도르프 요양원"],"pass1":[{"kind":"say","lines":["이 쪽은 **총체예술(Total Art)**이라는 생각을 소개해요.","건물만 짓고 끝내지 말고 가구, 바닥, 커튼까지 한 사람이 다 디자인하자는 거예요.","그 대표 선수가 **요제프 호프만**이에요."]},{"kind":"analogy","head":"총체예술은 한 벌 맞춤","scene":"옷, 신발, 가방, 시계를 한 디자이너가 세트로 맞춘 것 같은 상태예요.","map":[["옷 한 벌 전체","건축에서 가구까지 전부"],["맞춤 장인의 손바느질","대량생산 반대, 장인적 기술과 재료"],["비싼 맞춤 값","부유층을 상대하는 값비싼 디자인이라는 한계"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**총체예술(Total Art)**: 건물부터 가구, 문손잡이까지 하나의 통일된 앙상블로 만드는 개념이에요.","독일어로는 Gesamtkunstwerk 라고 써요. 시험에 독일어 이름이 그대로 나와요.","**요제프 호프만**: 1870-1956. 사각형을 반복해서 '사각형의 호프만'이라 불린 건축가예요.","**푸커스도르프 요양원**: 호프만이 오스트리아 푸커스도르프에 지은 1905년 요양원이에요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["예술가가 건축에서 가구까지 삶의 예술에 관한 모든 부분에 대해 작업해야 한다는 견해예요.","예술 속의 다양한 장르의 구분과 서열을 부정해요.","예술과 생활, 예술과 수공예, 건축물과 장식을 구분하지 않고 하나의 작품으로 완성해요.","대량생산을 반대하고 장인적인 기술과 재료를 사용해요.","주택의 경우 대량생산 방식과는 거리가 있고 부유층을 상대하는 값비싼 디자인이에요."]},{"kind":"look","walked":1},{"kind":"compare","head":"**총체예술(Total Art)** 은 무엇을 반대할까요","cols":["항목","총체예술의 태도"],"rows":[["예술 장르의 서열","구분과 서열을 부정해요"],["대량생산","반대하고 장인적 기술과 재료를 써요"],["예술과 생활의 분리","구분하지 않고 하나의 작품으로 합쳐요"]]}],"pass3":[{"kind":"check","q":"**푸커스도르프 요양원**은 몇 년 작품일까요?","choices":["1898","1905","1911"],"a":1,"why":"1905년, 오스트리아 푸커스도르프예요. 스토클레 저택(1911)보다 앞서요."},{"kind":"check","q":"**요제프 호프만**이 대량생산에 대해 취한 태도는?","choices":["적극 수용했어요","반대하고 장인적 기술을 썼어요","관심이 없었어요"],"a":1,"why":"대량생산 반대, 장인적 기술과 재료. 그래서 부유층 대상의 값비싼 디자인이 한계예요."},{"kind":"english","head":"논술 답안: 총체예술","en":"총체예술은 예술가가 건축에서 가구까지 삶의 예술에 관한 모든 부분을 작업해야 한다는 견해로, 예술 장르의 구분과 서열을 부정하고 예술과 생활, 수공예를 하나의 작품으로 통합한다.","ko":"대량생산을 반대하고 장인적 기술과 재료를 사용하며, 주택은 부유층을 상대하는 값비싼 디자인이라는 한계를 가진다.","tip":"'장르 서열 부정 + 통합 + 대량생산 반대 + 값비싼 한계' 네 가지를 꼭 써요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.55,0.07],"c":[0.0125,0.0139,0.605,0.1222],"r":6.6012,"img":"img/U3/walk/p003_22_01.jpg","say":"제목. 총체예술(Total Art: Gesamtkunstwerk)."},{"b":[0.44,0.11,0.5,0.05],"c":[0.415,0.0794,0.55,0.1111],"r":6.6007,"img":"img/U3/walk/p003_22_02.jpg","say":"호프만의 생몰년 1870-1956. 시험에 그대로 나와요."},{"b":[0.04,0.18,0.92,0.34],"c":[0.0,0.163,1,0.374],"r":3.5651,"img":"img/U3/walk/p003_22_03.jpg","say":"총체예술의 다섯 가지 내용이에요. 마지막 줄의 '값비싼 디자인'이 한계예요."},{"b":[0.05,0.6,0.42,0.31],"c":[0.029,0.584,0.462,0.342],"r":1.8012,"img":"img/U3/walk/p003_22_04.jpg","say":"**푸커스도르프 요양원** 실내예요. 검은색과 흰색의 기하학적 바닥 패턴이 보여요."},{"b":[0.54,0.6,0.43,0.31],"c":[0.5185,0.584,0.473,0.342],"r":1.8441,"img":"img/U3/walk/p003_22_05.jpg","say":"같은 요양원 외관이에요. 흰 벽에 창을 규칙적으로 뚫은 납작한 상자 모양이에요."},{"b":[0.4,0.93,0.55,0.05],"c":[0.3725,0.8778,0.605,0.1222],"r":6.6012,"img":"img/U3/walk/p003_22_06.jpg","say":"캡션. 요제프 호프만, 푸커스도르프 요양원, 오스트리아 푸커스도르프, 1905."}]}},{"p":4,"title":"요제프 호프만, 스토클레 저택, 벨기에 브뤼셀, 1911","terms":["스토클레 저택","요제프 호프만","Total Art"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **스토클레 저택**의 바깥 모습이에요.","**요제프 호프만**이 1911년 벨기에 브뤼셀에 지은 저택이에요.","**총체예술(Total Art)**을 실제로 실현하려 한 대표작이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **요제프 호프만**, 연도는 1911년, 장소는 벨기에 브뤼셀이에요.","빈이 아니라 브뤼셀이에요. O/X 문제로 자주 나와요.","벽이 매끈한 판으로 덮여 있고 모서리마다 가는 금속 띠가 둘러져 있어요.","창과 벽이 모두 네모라서 **스토클레 저택**은 사각형이 반복되는 인상을 줘요.","가운데 탑이 높이 솟아 있고 꼭대기에 사람 조각상들이 서 있어요."]},{"kind":"look","walked":1},{"kind":"bg","src":"배경 지식","lines":["저택의 이름은 주인인 스토클레의 성에서 왔어요.","강의자료는 위치와 연도만 알려 주니 그 두 가지만 외우면 돼요."]}],"pass3":[{"kind":"check","q":"**스토클레 저택**은 어디에 있을까요?","choices":["오스트리아 빈","벨기에 브뤼셀","독일 다름슈타트"],"a":1,"why":"벨기에 브뤼셀, 1911년이에요. 빈이라고 하면 틀려요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.09,0.88,0.85],"c":[0.016,0.0475,0.968,0.935],"r":1.3804,"img":"img/U3/walk/p004_21_01.jpg","say":"사진 전체. 호프만의 스토클레 저택 정면이에요."},{"b":[0.45,0.19,0.15,0.62],"c":[0.3924,0.159,0.2652,0.682],"r":0.5185,"img":"img/U3/walk/p004_21_02.jpg","say":"가운데 솟은 탑. 맨 위에 조각상이 있고 아래로 긴 창이 이어져요."},{"b":[0.06,0.47,0.35,0.3],"c":[0.0425,0.454,0.385,0.332],"r":1.5462,"img":"img/U3/walk/p004_21_03.jpg","say":"왼쪽 몸체. 평평한 석판 벽에 네모 창이 규칙적으로 뚫려 있어요."},{"b":[0.6,0.5,0.33,0.25],"c":[0.5835,0.484,0.363,0.282],"r":1.7163,"img":"img/U3/walk/p004_21_04.jpg","say":"오른쪽 담장. 벽과 같은 석판으로 이어져 건물과 정원이 한 덩어리예요."},{"b":[0.57,0.94,0.41,0.05],"c":[0.549,0.89,0.451,0.11],"r":5.4667,"img":"img/U3/walk/p004_21_05.jpg","say":"캡션. 요제프 호프만, 스토클레 저택, 벨기에 브뤼셀, 1911."}]}},{"p":5,"title":"스토클레 저택 식당: 호프만이 전부 디자인하고 클림트가 벽화를 맡다","terms":["스토클레 저택","요제프 호프만","구스타프 클림트"],"pass1":[{"kind":"say","lines":["이 쪽은 **스토클레 저택**의 식당 이야기예요.","붙박이 캐비닛, 바닥 타일, 카펫, 가구를 모두 **요제프 호프만**이 디자인했어요.","벽의 모자이크 벽화만 화가 **구스타프 클림트**가 맡았어요."]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["격식을 갖춘 다이닝룸에서 호프만은 붙박이 캐비닛과 바닥 타일, 카펫, 가구들을 디자인했어요.","검은색과 흰색의 바닥 타일, 어두운 색의 가구가 나와요.","그것들이 대리석 벽의 따뜻한 색과 측면 모자이크 벽화 덕분에 환하게 보여요.","모자이크 벽화는 **구스타프 클림트**가 디자인하고 대리석, 유리, 준보석으로 제작했어요.","디자인 통합을 위해 사각형 요소를 반복 사용해서 '사각형의 호프만'이라 불려요. 맥킨토시의 영향이에요."]},{"kind":"look","walked":1},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["벽화 재료는 대리석, 유리, 준보석 세 가지예요. 나무는 아니에요.","바닥 타일 색은 검은색과 흰색이에요.","'사각형의 호프만' 별명은 맥킨토시의 영향과 함께 나와요."]}],"pass3":[{"kind":"check","q":"**스토클레 저택** 모자이크 벽화의 재료가 아닌 것은?","choices":["대리석","유리","준보석","나무"],"a":3,"why":"대리석, 유리, 준보석이에요. 나무는 안 나와요."},{"kind":"check","q":"사각형 요소를 반복 사용해서 붙은 **요제프 호프만**의 별명은?","choices":["곡선의 호프만","사각형의 호프만","유리의 호프만"],"a":1,"why":"'사각형의 호프만'이에요. 맥킨토시의 영향으로 설명해요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.92,0.3],"c":[0.0,0.044,1,0.332],"r":4.0161,"img":"img/U3/walk/p005_21_01.jpg","say":"글 네 줄. 재료와 색, 클림트의 벽화, 사각형의 호프만이 다 들어 있어요."},{"b":[0.04,0.48,0.44,0.34],"c":[0.018,0.463,0.484,0.374],"r":1.7255,"img":"img/U3/walk/p005_21_02.jpg","say":"**스토클레 저택** 평면도예요. 방들이 네모로 잘려 붙어 있어요."},{"b":[0.48,0.42,0.47,0.46],"c":[0.4565,0.397,0.517,0.506],"r":1.3623,"img":"img/U3/walk/p005_21_03.jpg","say":"**구스타프 클림트**의 모자이크 벽화예요. 금색 소용돌이 나뭇가지가 화면을 가득 채워요."},{"b":[0.48,0.55,0.22,0.3],"c":[0.468,0.534,0.244,0.332],"r":0.9799,"img":"img/U3/walk/p005_21_04.jpg","say":"소용돌이 곡선을 자세히 봐요. 호프만의 네모와 정반대 성격이에요."}]}},{"p":6,"title":"구스타프 클림트가 제작한 스토클레 저택 식당의 벽화","terms":["구스타프 클림트","스토클레 저택"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **구스타프 클림트**가 만든 식당 벽화예요.","**스토클레 저택** 식당의 옆벽을 덮고 있는 모자이크예요.","금색 소용돌이가 화면 전체를 휘감아요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 '클림트가 제작한 식당의 벽화' 한 줄뿐이에요. 다른 정보는 슬라이드에 없어요.","금색 바탕에 소용돌이 모양 나뭇가지가 좌우로 뻗어 있어요.","가운데에 사람 형상이 하나 서 있고, 삼각형을 겹쳐 쌓은 옷을 입고 있어요.","재료는 앞 쪽에서 말한 대로 대리석, 유리, 준보석이에요.","이 곡선이 **요제프 호프만**의 사각형과 짝을 이뤄요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.06,0.06,0.88,0.87],"c":[0.016,0.0165,0.968,0.957],"r":1.3487,"img":"img/U3/walk/p006_21_01.jpg","say":"벽화 전체예요. 금색 소용돌이가 반복돼요."},{"b":[0.38,0.12,0.22,0.75],"c":[0.3296,0.0825,0.3208,0.825],"r":0.5185,"img":"img/U3/walk/p006_21_02.jpg","say":"가운데 사람 형상. 삼각형 무늬 옷이 아래로 길게 흘러요."},{"b":[0.07,0.25,0.28,0.45],"c":[0.056,0.2275,0.308,0.495],"r":0.8296,"img":"img/U3/walk/p006_21_03.jpg","say":"왼쪽 소용돌이. 나뭇가지가 돌돌 말린 모양이에요."},{"b":[0.3,0.94,0.4,0.05],"c":[0.28,0.89,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p006_21_04.jpg","say":"캡션. 클림트가 제작한 식당의 벽화."}]}},{"p":7,"title":"스토클레 저택의 식당: 호프만의 사각형과 클림트의 곡선이 이루는 대위법","terms":["스토클레 저택","요제프 호프만","구스타프 클림트","대위법","Total Art"],"pass1":[{"kind":"say","lines":["이 쪽이 3강에서 가장 자주 나오는 문장을 담고 있어요.","**요제프 호프만**의 사각형과 **구스타프 클림트**의 소용돌이 곡선이 **대위법**으로 짜였어요.","**스토클레 저택**은 모든 디자인이 통합된 심포니 같은 건축이에요."]},{"kind":"analogy","head":"대위법은 두 악기의 합주","scene":"낮은 북이 또박또박 치는 위로 바이올린이 구불구불 흐르는 연주 같아요.","map":[["또박또박 치는 북","호프만의 수평선, 수직선, 정사각형"],["구불구불한 바이올린","클림트의 부드러운 소용돌이 곡선"],["둘이 어울리는 합주","긴장감을 만들면서 상호 보완하는 **대위법**"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["호프만은 **스토클레 저택**을 통해 꿈꾸어 오던 건축의 이상을 실현하고자 했어요.","즉 모든 디자인이 통합된 오케스트라 연주 같은 심포니로서의 건축이에요.","호프만의 사각형과 클림트의 소용돌이 곡선이 **대위법**적으로 구성돼요.","딱딱한 수평선과 수직선, 정사각형과 직사각형이 긴장감을 형성해요.","부드러운 소용돌이 곡선이 대비를 이루면서 상호 보완 역할을 해요."]},{"kind":"points","head":"**총체예술(Total Art)** 이 여기서 완성돼요","items":["건물, 식당, 캐비닛, 타일, 카펫, 가구, 벽화가 한 사람의 계획 아래 들어왔어요.","장르의 서열이 없으니 화가 **구스타프 클림트**도 같은 작품의 공동 저자예요.","그래서 '오케스트라 연주 같은 심포니로서의 건축'이라는 표현을 써요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**스토클레 저택**에서 호프만의 사각형과 클림트의 곡선이 이루는 관계는?","choices":["서로 무관해요","**대위법**적으로 긴장과 상호 보완을 이뤄요","곡선이 사각형을 덮어요"],"a":1,"why":"딱딱한 직선이 긴장을 만들고 부드러운 곡선이 대비되며 서로 보완해요."},{"kind":"check","q":"호프만이 스토클레 저택에서 실현하려 한 건축의 이상을 비유한 표현은?","choices":["기계 같은 건축","오케스트라 연주 같은 심포니로서의 건축","동굴 같은 건축"],"a":1,"why":"'모든 디자인이 통합된 오케스트라 연주 같은 심포니로서의 건축'이에요."},{"kind":"english","head":"논술 답안: 스토클레 저택","en":"스토클레 저택은 요제프 호프만이 1911년 벨기에 브뤼셀에 설계한 저택으로, 붙박이 캐비닛과 바닥 타일, 카펫, 가구를 모두 디자인하고 클림트가 대리석과 유리, 준보석의 모자이크 벽화를 제작하였다.","ko":"호프만의 사각형과 클림트의 소용돌이 곡선이 대위법적으로 구성되어 긴장과 상호 보완을 이루며, 모든 디자인이 통합된 심포니로서의 건축을 실현하였다.","tip":"'호프만 + 1911 + 브뤼셀 + 클림트 모자이크 + 대위법 + 심포니' 순서로 써요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.06,0.92,0.28],"c":[0.0,0.044,1,0.312],"r":4.2735,"img":"img/U3/walk/p007_22_01.jpg","say":"글 세 줄. 심포니로서의 건축, 대위법, 긴장과 상호 보완."},{"b":[0.05,0.36,0.46,0.58],"c":[0.027,0.331,0.506,0.638],"r":1.0575,"img":"img/U3/walk/p007_22_02.jpg","say":"식당 사진. 긴 식탁과 어두운 의자, 검은색과 흰색 바닥 타일이 보여요."},{"b":[0.09,0.78,0.38,0.14],"c":[0.071,0.764,0.418,0.172],"r":3.2403,"img":"img/U3/walk/p007_22_03.jpg","say":"바닥을 봐요. 검은색과 흰색 타일이 네모 격자로 깔렸어요."},{"b":[0.05,0.4,0.14,0.28],"c":[0.02,0.384,0.2,0.312],"r":0.8547,"img":"img/U3/walk/p007_22_04.jpg","say":"왼쪽 벽면의 금색 모자이크. 여기가 클림트의 소용돌이 곡선이에요."},{"b":[0.57,0.36,0.28,0.63],"c":[0.556,0.307,0.308,0.693],"r":0.5926,"img":"img/U3/walk/p007_22_05.jpg","say":"오른쪽 벽화 확대. 네모 격자와 소용돌이가 한 화면에 같이 있어요. 아래 캡션에 클림트가 제작한 식당의 벽화라고 적혀 있어요."},{"b":[0.05,0.94,0.55,0.04],"c":[0.0225,0.8778,0.605,0.1222],"r":6.6012,"img":"img/U3/walk/p007_22_06.jpg","say":"캡션. 요제프 호프만, 스토클레 저택의 식당, 벨기에 브뤼셀, 1911."}]}},{"p":8,"title":"빈 분리파(Wiener Secession): 1897년 클림트가 결성","terms":["Wiener Secession","구스타프 클림트"],"pass1":[{"kind":"say","lines":["이 쪽부터 두 번째 주인공 **빈 분리파(Wiener Secession)**예요.","1897년에 화가 **구스타프 클림트**가 만든 예술가 조직이에요.","'분리'는 고루한 기성 예술과 갈라서겠다는 뜻이에요."]},{"kind":"analogy","head":"분리파는 탈퇴 선언","scene":"동아리가 너무 고리타분해서 몇 명이 나와 새 동아리를 만든 것 같아요.","map":[["나온 사람들","클림트와 뜻이 같은 예술가들"],["새 동아리 이름","**빈 분리파(Wiener Secession)**, 독일어로 제체시온"],["새 동아리 규칙","장르 구분 없애기, 개인 존중, 생활과 미술 잇기"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**빈 분리파(Wiener Secession)**: 1897년 결성된 조직이에요. 제체시온이라고도 불러요.","**구스타프 클림트**: 분리파를 이끈 화가예요. 베토벤 프리즈와 스토클레 모자이크를 그렸어요.","Secession 은 '떨어져 나온다'는 뜻이에요. 그래서 분리파라고 옮겨요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["구스타프 클림트가 비슷한 견해를 갖는 예술가들을 이끌고 1897년 분리파를 결성했어요.","제체시온은 기성 사회의 근엄한 예술에 반기를 들었어요.","이 시기 건축과 예술 운동의 공통 목표는 미술과 생활 사이의 새로운 관계를 모색하는 것이었어요.","그것이 삶과 예술을 결합시킬 수 있는 방법이라고 인식했어요.","예술가 개인의 특성을 존중하고 예술 장르간의 구분을 없애고 통합하려 노력했어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빈 분리파(Wiener Secession)**가 결성된 해는?","choices":["1890년","1897년","1905년"],"a":1,"why":"1897년, 클림트가 결성했어요. 전시관은 이듬해 1898년이에요."},{"kind":"check","q":"빈 분리파가 반기를 든 대상은?","choices":["기성 사회의 근엄한 예술","산업 생산","노동 조합"],"a":0,"why":"기성 사회의 근엄한 예술이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["결성은 1897년, 전시관 준공은 1898년이에요. 한 해 차이를 노려요.","빈 분리파는 장르 구분을 '없애려' 했어요. 강화한다고 하면 틀려요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.14,0.42,0.07],"c":[0.019,0.12,0.462,0.11],"r":5.6,"img":"img/U3/walk/p008_22_01.jpg","say":"제목. 빈 분리파(Wiener Secession)."},{"b":[0.04,0.23,0.52,0.18],"c":[0.014,0.214,0.572,0.212],"r":3.5975,"img":"img/U3/walk/p008_22_02.jpg","say":"첫 항목. 클림트가 1897년 결성, 제체시온이라는 이름."},{"b":[0.04,0.42,0.52,0.12],"c":[0.014,0.404,0.572,0.152],"r":5.0175,"img":"img/U3/walk/p008_22_03.jpg","say":"둘째 항목. 기성 사회의 근엄한 예술에 반기."},{"b":[0.04,0.55,0.52,0.19],"c":[0.014,0.534,0.572,0.222],"r":3.4354,"img":"img/U3/walk/p008_22_04.jpg","say":"셋째 항목. 미술과 생활 사이의 새로운 관계라는 공통 목표."},{"b":[0.04,0.76,0.52,0.1],"c":[0.014,0.744,0.572,0.132],"r":5.7778,"img":"img/U3/walk/p008_22_05.jpg","say":"넷째 항목. 개인 존중과 장르 구분 폐지."},{"b":[0.59,0.02,0.38,0.97],"c":[0.571,0,0.418,1],"r":0.5573,"img":"img/U3/walk/p008_22_06.jpg","say":"**구스타프 클림트(Gustav Klimt)** 의 제체시온 전시 포스터예요. 아래 캡션에도 그렇게 적혀 있어요."}]}},{"p":9,"title":"분리파 전시관: 요제프 마리아 올브리히, 오스트리아 빈, 1898","terms":["분리파 전시관","요제프 마리아 올브리히","구스타프 클림트","베토벤 프리즈","Wiener Secession"],"pass1":[{"kind":"say","lines":["**분리파 전시관**은 **빈 분리파(Wiener Secession)**의 집이에요.","설계자는 **요제프 마리아 올브리히**, 1898년 오스트리아 빈이에요.","**구스타프 클림트** 주도로 지었고, 지하에 **베토벤 프리즈**가 있어요."]},{"kind":"say","lines":["지붕에 금색 공이 얹혀 있어요. 월계수 잎을 금으로 만든 돔이에요.","빈 사람들은 이 돔을 보고 '금빛 양배추'라고 부르기도 했대요.","시험에는 설계자, 연도, 클림트의 작품 이름이 나와요."]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**분리파 전시관**: 1898년 빈에 세운 **빈 분리파(Wiener Secession)**의 전시 건물이에요.","**요제프 마리아 올브리히**: 분리파 전시관과 다름슈타트 예술가회관을 지은 건축가예요.","**베토벤 프리즈**: **구스타프 클림트**가 전시관 지하 전시장에 제작한 작품이에요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["오른쪽이 **분리파 전시관**이에요. 흰 벽의 네모 덩어리 위에 금색 돔이 올라앉아 있어요.","돔은 금색 월계수 잎을 엮어 만든 모양이에요.","정면 위쪽에 금색 글씨로 표어가 새겨져 있어요.","왼쪽은 클림트가 그린 제1회 분리파 전시회 포스터예요. 테세우스와 미노타우로스가 나와요.","설계는 **요제프 마리아 올브리히**, 건립 주도는 **구스타프 클림트**로 나눠서 외워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**분리파 전시관**을 설계한 사람은?","choices":["요제프 호프만","**요제프 마리아 올브리히**","오토 바그너"],"a":1,"why":"올브리히예요. 클림트는 건립을 주도했고, 지하에 베토벤 프리즈를 그렸어요."},{"kind":"check","q":"**구스타프 클림트**가 분리파 전시관 지하에 제작한 작품은?","choices":["**베토벤 프리즈**","키스","생명의 나무"],"a":0,"why":"베토벤 프리즈예요. 지하 전시장에 있어요."},{"kind":"english","head":"논술 답안: 분리파 전시관","en":"분리파 전시관은 요제프 마리아 올브리히가 1898년 오스트리아 빈에 설계한 건물로, 구스타프 클림트 주도로 건립되었고 클림트는 지하 전시장에 베토벤 프리즈를 제작하였다.","ko":"정면에는 각 시대에는 고유한 예술을, 예술에는 자유를 이라는 표어가, 측면에는 Ver Sacrum 이 새겨져 있다.","tip":"'올브리히 설계, 클림트 주도, 1898, 빈' 네 가지를 한 문장에 넣어요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.3,0.06],"c":[0.035,0.025,0.33,0.11],"r":4.0,"img":"img/U3/walk/p009_22_01.jpg","say":"제목. 분리파 전시관."},{"b":[0.05,0.11,0.62,0.11],"c":[0.019,0.094,0.682,0.142],"r":6.4038,"img":"img/U3/walk/p009_22_02.jpg","say":"두 줄 글. 클림트 주도로 건립, 지하 전시장에 베토벤 프리즈."},{"b":[0.12,0.37,0.31,0.61],"c":[0.1045,0.329,0.341,0.671],"r":0.6776,"img":"img/U3/walk/p009_22_03.jpg","say":"클림트의 제1회 분리파 전시회 포스터예요. 캡션에 테세우스와 미노타우로스가 등장한다고 적혀 있어요."},{"b":[0.6,0.23,0.36,0.22],"c":[0.582,0.214,0.396,0.252],"r":2.0952,"img":"img/U3/walk/p009_22_04.jpg","say":"금색 월계수 잎 돔. 전시관에서 가장 먼저 눈에 띄는 부분이에요."},{"b":[0.53,0.47,0.3,0.06],"c":[0.515,0.445,0.33,0.11],"r":4.0,"img":"img/U3/walk/p009_22_05.jpg","say":"정면 위 금색 글씨가 표어예요. 다음 쪽에서 크게 봐요."},{"b":[0.47,0.55,0.5,0.44],"c":[0.445,0.516,0.55,0.484],"r":1.5152,"img":"img/U3/walk/p009_22_06.jpg","say":"흰 벽의 네모 덩어리. 장식은 금색 띠로만 붙어 있어요. 캡션은 요제프 마리아 올브리히, 분리파 전시관, 오스트리아 빈, 1898 이에요."}]}},{"p":10,"title":"분리파 전시관의 표어, Ver Sacrum, 뱀 머리 부적","terms":["분리파 전시관","Ver Sacrum","뱀 머리 부적","Wiener Secession","요제프 마리아 올브리히"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. **분리파 전시관**에 새겨진 글씨와 조각을 크게 찍었어요.","정면 표어는 '각 시대에는 고유한 예술을, 예술에는 자유를'이에요.","측면에는 **성스러운 봄(Ver Sacrum)**, 입구 위에는 **뱀 머리 부적**이 있어요."]},{"kind":"say","lines":["세 가지 다 **빈 분리파(Wiener Secession)**의 선언문 같은 거예요.","옛 예술과 갈라서고 새 시대의 예술을 하겠다는 뜻이에요.","표어, Ver Sacrum, 부적 세 낱말을 한 세트로 외워요."]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**성스러운 봄(Ver Sacrum)**: **분리파 전시관** 측면에 새긴 라틴어 문구예요.","**뱀 머리 부적**: 회화, 조각, 건축을 뜻하며 과거의 낡은 정신을 몰아내는 상징이에요.","정면 표어의 독일어 원문은 DER ZEIT IHRE KUNST, DER KUNST IHRE FREIHEIT 예요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["위 사진은 정면 처마 밑이에요. 금색 대문자로 표어가 두 줄 새겨져 있어요.","글씨 위로는 금색 덩굴 장식이 띠처럼 붙어 있어요.","왼쪽 아래는 측면 벽이에요. VER SACRVM 이라는 금색 글씨가 작게 보여요.","오른쪽 아래는 여자 얼굴 셋과 뱀이 얽힌 부조예요. 아래에 MALEREI, ARCHITEKTUR, PLASTIK 이라 쓰여 있어요.","그 세 낱말이 곧 회화, 건축, 조각이고 그것이 **뱀 머리 부적**의 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**분리파 전시관** 측면에 새겨진 문구 **성스러운 봄(Ver Sacrum)**의 뜻은?","choices":["신성한 불","성스러운 봄","영원한 예술"],"a":1,"why":"Ver Sacrum 은 성스러운 봄이에요."},{"kind":"check","q":"전시관의 **뱀 머리 부적**이 상징하는 것은?","choices":["회화, 조각, 건축","봄, 여름, 가을","과거, 현재, 미래"],"a":0,"why":"회화, 조각, 건축을 뜻하고 과거의 낡은 정신을 몰아내는 상징이에요."},{"kind":"english","head":"논술 답안: 분리파 전시관의 표어","en":"분리파 전시관 정면에는 각 시대에는 고유한 예술을, 예술에는 자유를 이라는 표어가 있고 측면에는 성스러운 봄을 뜻하는 Ver Sacrum 이 새겨져 있다.","ko":"회화, 조각, 건축을 뜻하는 뱀의 머리를 한 부적은 과거의 낡은 정신을 몰아내는 상징이다.","tip":"'표어 + Ver Sacrum + 뱀 머리 부적' 세 개를 묶어서 외워요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.02,0.54,0.48],"c":[0,0,0.594,0.528],"r":1.5,"img":"img/U3/walk/p010_22_01.jpg","say":"정면 처마의 금색 표어 두 줄이에요."},{"b":[0.47,0.5,0.5,0.05],"c":[0.445,0.4694,0.55,0.1111],"r":6.6007,"img":"img/U3/walk/p010_22_02.jpg","say":"한국어 번역. 각 시대에는 고유한 예술을, 예술에는 자유를."},{"b":[0.01,0.56,0.37,0.42],"c":[0,0.538,0.407,0.462],"r":1.1746,"img":"img/U3/walk/p010_22_03.jpg","say":"측면 벽의 VER SACRVM. 아래 캡션 그대로 Ver Sacrum 은 성스러운 봄이라는 뜻이에요."},{"b":[0.38,0.56,0.46,0.37],"c":[0.357,0.5415,0.506,0.407],"r":1.6577,"img":"img/U3/walk/p010_22_04.jpg","say":"뱀 머리 부적. 얼굴 셋과 뱀, 그리고 회화 건축 조각을 뜻하는 글씨예요."},{"b":[0.4,0.94,0.58,0.04],"c":[0.362,0.8711,0.638,0.1289],"r":6.5994,"img":"img/U3/walk/p010_22_05.jpg","say":"캡션. 낡은 정신을 몰아내는 상징이라고 적혀 있어요."}]}},{"p":11,"title":"구스타프 클림트, 베토벤 프리즈와 전시관의 입구, 측면","terms":["베토벤 프리즈","구스타프 클림트","분리파 전시관","Ver Sacrum"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. 아래 넓은 사진이 **베토벤 프리즈**예요.","**구스타프 클림트**가 **분리파 전시관** 지하 전시장에 그린 작품이에요.","위 두 장은 전시관의 입구 문과 측면 벽이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위는 전시관 입구예요. 문 옆에 도마뱀 모양 부조와 금색 덩굴이 붙어 있어요.","오른쪽 위는 측면이에요. 흰 벽 위쪽에 **성스러운 봄(Ver Sacrum)** 글씨가 보여요.","아래는 지하 전시장이에요. 벽 위쪽을 띠처럼 길게 두른 그림이 **베토벤 프리즈**예요.","프리즈는 벽 윗부분을 가로로 두르는 띠 모양 그림이나 조각을 말해요.","가운데 벽면에 금색과 파란색이 섞인 인물들이 몰려 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**베토벤 프리즈**는 **분리파 전시관**의 어디에 있을까요?","choices":["옥상","지하 전시장","정면 현관"],"a":1,"why":"클림트가 지하 전시장에 제작했어요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.03,0.47,0.48],"c":[0.0065,0.006,0.517,0.528],"r":1.3056,"img":"img/U3/walk/p011_21_01.jpg","say":"전시관 입구 문. 금색 덩굴 장식과 도마뱀 부조가 있어요."},{"b":[0.52,0.03,0.45,0.48],"c":[0.4975,0.006,0.495,0.528],"r":1.25,"img":"img/U3/walk/p011_21_02.jpg","say":"측면 벽. 오른쪽 위 금색 글씨가 VER SACRVM 이에요."},{"b":[0.13,0.54,0.74,0.4],"c":[0.093,0.52,0.814,0.44],"r":2.4667,"img":"img/U3/walk/p011_21_03.jpg","say":"지하 전시장. 벽 윗부분을 두른 띠 그림이 베토벤 프리즈예요."},{"b":[0.4,0.72,0.28,0.17],"c":[0.386,0.704,0.308,0.202],"r":2.033,"img":"img/U3/walk/p011_21_04.jpg","say":"가운데 벽면. 인물들이 금색과 파란색으로 빽빽하게 그려져 있어요."},{"b":[0.3,0.94,0.35,0.04],"c":[0.2825,0.89,0.385,0.11],"r":4.6667,"img":"img/U3/walk/p011_21_05.jpg","say":"캡션. Gustav Klimt, Beethoven Frieze."}]}},{"p":12,"title":"분리파 전시관의 장식 디테일 네 장면","terms":["분리파 전시관","요제프 마리아 올브리히","Wiener Secession"],"pass1":[{"kind":"say","lines":["글이 하나도 없는 사진 네 장이에요.","**분리파 전시관**의 장식을 가까이서 찍은 것들이에요.","**빈 분리파(Wiener Secession)**가 좋아한 장식 모양을 눈에 익혀 두는 쪽이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에는 글자 캡션이 없어요. 그래서 보이는 것만 말할게요.","왼쪽 위: 흰 벽에 덩굴이 고리처럼 얽힌 납작한 부조가 붙어 있어요.","오른쪽 위: 처마 밑 네모 칸 안에 잎사귀 무늬를 선으로만 그려 넣었어요.","왼쪽 아래: 금색 월계수 잎 돔을 아주 가까이서 찍었어요. 잎 하나하나가 따로 만들어져 있어요.","오른쪽 아래: 동그라미 여섯 개와 굽은 선이 얽힌 부조예요."]},{"kind":"points","head":"이 장식이 왜 중요한가요","items":["장식이 벽에서 툭 튀어나오지 않고 벽면에 얇게 붙어 있어요.","곡선을 쓰지만 아르누보처럼 제멋대로 흐르지 않고 네모 칸 안에 얌전히 들어가 있어요.","이것이 **분리파 전시관**과 **요제프 마리아 올브리히**의 장식 성격이에요.","주문을 떠올려요. 싫어 → 새 장식 → 정리 → 없애. 지금은 '정리' 단계예요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.01,0.02,0.43,0.47],"c":[0,0,0.473,0.517],"r":1.2199,"img":"img/U3/walk/p012_22_01.jpg","say":"덩굴이 고리처럼 얽힌 납작한 부조예요."},{"b":[0.5,0.02,0.48,0.47],"c":[0.472,0,0.528,0.517],"r":1.3617,"img":"img/U3/walk/p012_22_02.jpg","say":"처마 밑 네모 칸 안의 잎사귀 무늬. 선으로만 그렸어요."},{"b":[0.01,0.51,0.46,0.47],"c":[0,0.483,0.506,0.517],"r":1.305,"img":"img/U3/walk/p012_22_03.jpg","say":"금색 월계수 잎 돔의 확대예요."},{"b":[0.5,0.51,0.48,0.47],"c":[0.472,0.483,0.528,0.517],"r":1.3617,"img":"img/U3/walk/p012_22_04.jpg","say":"동그라미와 굽은 선이 얽힌 부조예요."}]}},{"p":13,"title":"오토 바그너와 빈의 모더니즘 (Otto Wagner, 1841-1918)","terms":["Otto Wagner","역사주의"],"pass1":[{"kind":"say","lines":["세 번째 주인공 **오토 바그너(Otto Wagner)**예요. 1841-1918년 사람이에요.","'필요만이 예술의 주인'이라고 말한 합리적 기능주의 건축가예요.","옛 양식을 베끼는 **역사주의**를 격퇴해야 한다고 주장했어요."]},{"kind":"analogy","head":"바그너는 실용파 선생님","scene":"'예쁘게만 하지 말고 쓸모 있게 만들어라'고 다그치는 선생님 같아요.","map":[["옛날 교과서 베끼기","**역사주의**, 바그너가 격퇴하려 한 것"],["필요한 것부터 정하기","'필요만이 예술의 주인'"],["새 재료로 새 모양 만들기","새 구조 방법이 새 형태를 만드는 이유"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**오토 바그너(Otto Wagner)**: 1841-1918. 빈의 합리적 기능주의 건축가예요.","**역사주의**: 과거의 고전적 형상에서 영감을 얻으려는 태도예요. 바그너는 여기에 반대했어요.","기능주의는 쓸모(기능)를 먼저 정하고 모양은 그다음에 따라오게 하는 태도예요."]},{"kind":"points","head":"슬라이드의 인용문과 항목 그대로","items":["건축가란 미를 추구해야 하는데, 그 미란 자연의 범례가 아니라 건축가의 독창적인 발상으로부터 창조되어야 해요.","과거의 고전적 형상에서 영감을 얻는 **역사주의**에 대한 반대 입장이에요.","'필요만이 예술의 주인'이며, 합리적이고 도시적인 문명에 유리하도록 역사주의를 격퇴해야 한다고 주장했어요.","새로운 목표는 새로운 구조 방법에 생명을 불어넣어야 하며, 이것이 새로운 형태가 만들어지는 이유예요.","새로운 양식은 현실적이어야 하며 구조의 의미, 새로운 기술과 재료의 적용, 사회적 열망의 전환을 직접 표현해야 해요."]},{"kind":"look","walked":1},{"kind":"bg","src":"배경 지식","lines":["'모더니즘'은 옛 양식을 버리고 지금 시대에 맞는 형태를 찾자는 흐름이에요.","빈에서는 **오토 바그너(Otto Wagner)**가 그 문을 열었어요."]}],"pass3":[{"kind":"check","q":"**오토 바그너(Otto Wagner)**의 생몰년은?","choices":["1841-1918","1870-1956","1870-1933"],"a":0,"why":"1841-1918이에요. 1870-1956은 호프만, 1870-1933은 로스예요."},{"kind":"check","q":"바그너가 말한 미의 원천은?","choices":["자연의 범례","건축가의 독창적인 발상","고전 건축의 비례"],"a":1,"why":"'자연의 범례로부터 찾는 것이 아니라 건축가의 독창적인 발상으로부터 창조'예요."},{"kind":"english","head":"논술 답안: 오토 바그너의 건축관","en":"오토 바그너는 미란 자연의 범례가 아니라 건축가의 독창적인 발상으로부터 창조되어야 한다고 보았으며, 과거의 고전적 형상에서 영감을 얻는 역사주의에 반대하였다.","ko":"필요만이 예술의 주인이라 하여 역사주의를 격퇴해야 한다고 주장하였고, 새로운 양식은 구조의 의미와 새로운 기술 및 재료의 적용, 사회적 열망의 전환을 직접 표현해야 한다고 하였다.","tip":"'독창적 발상 + 역사주의 반대 + 필요만이 주인 + 구조와 재료의 표현' 네 덩어리예요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.03,0.38,0.07],"c":[0.031,0.01,0.418,0.11],"r":5.0667,"img":"img/U3/walk/p013_22_01.jpg","say":"제목. 오토 바그너와 빈의 모더니즘."},{"b":[0.05,0.09,0.45,0.05],"c":[0.0275,0.06,0.495,0.11],"r":6.0,"img":"img/U3/walk/p013_22_02.jpg","say":"생몰년 1841-1918. 시험 단골이에요."},{"b":[0.05,0.17,0.65,0.17],"c":[0.0175,0.154,0.715,0.202],"r":4.7195,"img":"img/U3/walk/p013_22_03.jpg","say":"첫 인용문. 미는 자연의 범례가 아니라 건축가의 독창적 발상에서 나와요."},{"b":[0.05,0.4,0.65,0.34],"c":[0.0175,0.383,0.715,0.374],"r":2.549,"img":"img/U3/walk/p013_22_04.jpg","say":"세 항목. 역사주의 반대, 필요만이 예술의 주인, 새 구조가 새 형태를 만든다."},{"b":[0.7,0.19,0.25,0.6],"c":[0.6875,0.16,0.275,0.66],"r":0.5556,"img":"img/U3/walk/p013_22_05.jpg","say":"바그너의 옆모습 사진. 아래에 1841년 출생, 1918년 사망이 적혀 있어요."},{"b":[0.05,0.81,0.65,0.16],"c":[0.0175,0.794,0.715,0.192],"r":4.9653,"img":"img/U3/walk/p013_22_06.jpg","say":"둘째 인용문. 새 양식은 현실적이어야 한다는 선언이에요."}]}},{"p":14,"title":"오토 바그너, 칼스플라츠 역사, 오스트리아 빈, 1901","terms":["칼스플라츠 역사","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **칼스플라츠 역사**의 정면이에요.","**오토 바그너(Otto Wagner)**가 1901년 오스트리아 빈에 지은 지하철 역사예요.","정면 가운데에 KARLSPLATZ 라는 글씨가 붙어 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자는 **오토 바그너(Otto Wagner)**, 연도는 1901년, 장소는 오스트리아 빈이에요.","초록색으로 칠한 가는 철골 기둥과 보가 건물의 뼈대예요.","그 사이를 흰 대리석 판이 채우고 있어요. 뼈대와 채움이 눈으로 구분돼요.","가운데 반원형 아치 위에 해바라기 같은 금색 무늬가 둘러져 있어요.","장식이 남아 있지만 벽에서 튀어나오지 않고 납작하게 그려져 있어요.","역사(驛舍)는 기차나 전철의 역 건물을 말해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**칼스플라츠 역사**는 언제, 누가 지었을까요?","choices":["1898년 올브리히","1901년 **오토 바그너(Otto Wagner)**","1906년 호프만"],"a":1,"why":"오토 바그너, 오스트리아 빈, 1901년이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["바그너의 연도 순서를 외워요. 앙커하우스 1895 → 마욜리카하우스 1898 → 칼스플라츠 역사 1901.","그다음이 우편저축은행 1906, 노이슈티프트가세 1911이에요."]}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.9,0.82],"c":[0.005,0.039,0.99,0.902],"r":1.4634,"img":"img/U3/walk/p014_21_01.jpg","say":"사진 전체. 칼스플라츠 역사의 정면이에요."},{"b":[0.33,0.23,0.32,0.25],"c":[0.314,0.214,0.352,0.282],"r":1.6643,"img":"img/U3/walk/p014_21_02.jpg","say":"가운데 반원 아치와 그 둘레의 금색 무늬예요."},{"b":[0.41,0.44,0.18,0.05],"c":[0.398,0.41,0.204,0.11],"r":2.4727,"img":"img/U3/walk/p014_21_03.jpg","say":"KARLSPLATZ 라는 역 이름이 붙어 있어요."},{"b":[0.2,0.45,0.16,0.18],"c":[0.18,0.434,0.2,0.212],"r":1.2579,"img":"img/U3/walk/p014_21_04.jpg","say":"초록 철골 기둥과 흰 대리석 판. 뼈대와 채움이 나뉘어 보여요."},{"b":[0.4,0.93,0.4,0.05],"c":[0.38,0.89,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p014_21_05.jpg","say":"캡션. 오토 바그너, 칼스플라츠 역사, 오스트리아 빈, 1901."}]}},{"p":15,"title":"초록 철골과 흰 대리석, 금색 장식의 세부 (캡션 없는 쪽)","terms":["칼스플라츠 역사","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 세 장인데 글자 캡션이 하나도 없는 쪽이에요.","앞 쪽, 뒤 쪽과 같은 초록 철골과 흰 대리석이 보여요.","**칼스플라츠 역사**의 세부를 찍은 사진들로 읽으면 돼요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에는 캡션이 없어서 건물 이름이 글로 적혀 있지 않아요.","왼쪽: 초록색 나무 문과 그 둘레의 흰 대리석 판이에요. 금색 선 장식이 얇게 그려져 있어요.","오른쪽 위: 실내 천장 모서리예요. 흰 벽과 초록 굽도리, 금색 무늬가 나란히 있어요.","오른쪽 아래: 실내 벽에 붙은 둥근 시계와 금색 선 장식이에요.","세 장 모두 초록, 흰색, 금색 세 가지 색으로만 이뤄져 있어요."]},{"kind":"points","head":"무엇을 봐야 할까요","items":["장식이 선으로만 그려져 있고 벽면에서 툭 튀어나오지 않아요.","**오토 바그너(Otto Wagner)**가 말한 대로 구조(철골)와 마감(대리석)이 눈에 구분돼요.","**칼스플라츠 역사**는 아직 장식이 남아 있는 시기의 작품이에요.","1906년 우편저축은행에 가면 이 장식마저 사라져요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.05,0.52,0.92],"c":[0.004,0,0.572,1],"r":0.7627,"img":"img/U3/walk/p015_22_01.jpg","say":"초록 문과 흰 대리석 판, 금색 선 장식이에요."},{"b":[0.56,0.05,0.43,0.45],"c":[0.527,0.0275,0.473,0.495],"r":1.2741,"img":"img/U3/walk/p015_22_02.jpg","say":"실내 천장 모서리. 흰색, 초록, 금색만 써요."},{"b":[0.56,0.51,0.43,0.46],"c":[0.527,0.487,0.473,0.506],"r":1.2464,"img":"img/U3/walk/p015_22_03.jpg","say":"둥근 시계와 금색 선 장식이에요."}]}},{"p":16,"title":"오토 바그너, 칼스플라츠 역사, 오스트리아 빈, 1901 (세부)","terms":["칼스플라츠 역사","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. 모두 **칼스플라츠 역사**의 세부예요.","**오토 바그너(Otto Wagner)**가 1901년 빈에 지은 지하철 역사예요.","아래 큰 사진에 KARLSPLATZ 라는 글씨가 또 보여요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위는 실내 천장이에요. 흰 바탕에 금색 선과 무늬가 띠처럼 둘러져 있어요.","오른쪽 위는 금색 장식 하나를 크게 찍은 거예요. 둥근 고리와 잎 모양이 섞여 있어요.","아래는 정면 아치를 올려다본 사진이에요. 초록 철골과 흰 대리석, 금색 해바라기 무늬가 보여요.","장식은 벽에서 튀어나오지 않고 판 위에 납작하게 붙어 있어요.","**칼스플라츠 역사**는 아직 장식이 남아 있는 시기의 **오토 바그너(Otto Wagner)** 작품이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**칼스플라츠 역사**에서 흰 대리석 판을 붙들고 있는 뼈대의 재료는 무엇으로 보이나요?","choices":["나무","초록색으로 칠한 철골","벽돌"],"a":1,"why":"가는 철골에 초록색을 칠했고 그 사이를 대리석 판이 채워요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.02,0.4,0.37],"c":[0.01,0.0015,0.44,0.407],"r":1.4414,"img":"img/U3/walk/p016_21_01.jpg","say":"실내 천장. 흰 바탕에 금색 선 장식이 띠처럼 돌아요."},{"b":[0.47,0.02,0.42,0.37],"c":[0.449,0.0015,0.462,0.407],"r":1.5135,"img":"img/U3/walk/p016_21_02.jpg","say":"금색 장식 하나를 크게 찍은 사진이에요."},{"b":[0.42,0.4,0.56,0.58],"c":[0.384,0.362,0.616,0.638],"r":1.2874,"img":"img/U3/walk/p016_21_03.jpg","say":"정면 아치. 초록 철골과 흰 대리석 판이 짝을 이뤄요."},{"b":[0.58,0.75,0.22,0.06],"c":[0.568,0.725,0.244,0.11],"r":2.9576,"img":"img/U3/walk/p016_21_04.jpg","say":"아치 안쪽에 KARLSPLATZ 라는 역 이름이 보여요."},{"b":[0.03,0.94,0.4,0.05],"c":[0.01,0.89,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p016_21_05.jpg","say":"캡션. 오토 바그너, 칼스플라츠 역사, 오스트리아 빈, 1901."}]}},{"p":17,"title":"오토 바그너, 앙커하우스, 오스트리아 빈, 1895","terms":["앙커하우스","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진과 도면이 함께 있어요. **앙커하우스**예요.","**오토 바그너(Otto Wagner)**가 1895년 오스트리아 빈에 지은 건물이에요.","3강에 나오는 바그너 작품 중 가장 이른 것이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["설계자는 **오토 바그너(Otto Wagner)**, 연도는 1895년, 장소는 오스트리아 빈이에요.","위는 평면도예요. 길이 꺾이는 자리에 맞춰 건물이 두 덩어리로 꺾여 있어요.","아래 왼쪽은 파사드를 올려다본 사진이에요. 창 아래마다 쇠로 만든 난간이 달려 있어요.","벽에는 아직 옛날식 띠 장식과 창틀 테두리가 남아 있어요.","아래 오른쪽은 길모퉁이에서 본 전체 모습이에요. 1층은 유리로 크게 뚫려 있어요.","1895년이라 **앙커하우스**는 아직 옛 양식의 흔적이 많이 남아 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**오토 바그너(Otto Wagner)**의 작품 연도 순서로 옳은 것은?","choices":["앙커하우스 1895 → 마욜리카하우스 1898 → 칼스플라츠 역사 1901","칼스플라츠 역사 1895 → 앙커하우스 1898 → 마욜리카하우스 1901","마욜리카하우스 1895 → 칼스플라츠 역사 1898 → 앙커하우스 1901"],"a":0,"why":"앙커하우스 1895, 마욜리카하우스와 링케 빈 차일레 1898, 칼스플라츠 역사 1901이에요."}],"walk":{"head":null,"parts":[{"b":[0.01,0.01,0.64,0.39],"c":[0,0,0.704,0.429],"r":2.188,"img":"img/U3/walk/p017_21_01.jpg","say":"평면도. 길이 꺾이는 자리에 맞춰 두 덩어리로 꺾여 있어요."},{"b":[0.07,0.41,0.49,0.52],"c":[0.0455,0.384,0.539,0.572],"r":1.2564,"img":"img/U3/walk/p017_21_02.jpg","say":"파사드 확대. 창 아래 쇠 난간과 옛날식 띠 장식이 보여요."},{"b":[0.63,0.42,0.29,0.51],"c":[0.6155,0.3945,0.319,0.561],"r":0.7582,"img":"img/U3/walk/p017_21_03.jpg","say":"길모퉁이에서 본 전체. 1층이 유리로 크게 뚫려 있어요."},{"b":[0.57,0.95,0.37,0.04],"c":[0.5515,0.89,0.407,0.11],"r":4.9333,"img":"img/U3/walk/p017_21_04.jpg","say":"캡션. 오토 바그너, 앙커하우스, 오스트리아 빈, 1895."}]}},{"p":18,"title":"바그너의 길: 제체시온 경향에서 합리적 기능주의로, 무대는 대도시","terms":["Otto Wagner","Wiener Secession","Art Nouveau"],"pass1":[{"kind":"say","lines":["이 쪽은 **오토 바그너(Otto Wagner)**가 어느 쪽으로 갔는지 말해요.","**빈 분리파(Wiener Secession)**나 **아르 누보(Art Nouveau)** 냄새를 풍기면서도,","결국 현실적이고 냉철한 합리적 기능주의자의 길을 걸었어요."]},{"kind":"analogy","head":"두 갈래 길에서","scene":"예쁜 장식 길과 쓸모 있는 길이 갈라지는 곳에 바그너가 서 있어요.","map":[["예쁜 장식 길","**빈 분리파(Wiener Secession)**와 **아르 누보(Art Nouveau)**의 경향"],["바그너가 고른 길","현실적이고 냉철한 합리적 기능주의"],["그 길이 향한 곳","근대적 변혁이 초래할 '대도시'라는 환경"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["바그너는 제체시온 또는 **아르 누보(Art Nouveau)** 양식의 경향을 보였음에도 합리적 기능주의자의 길을 걷게 됐어요.","제체시온은 **빈 분리파(Wiener Secession)**의 다른 이름이에요.","건축은 근대 도시 생활에서의 실용예술을 완벽하게 보여주는 것이라 했어요.","이에 건축의 문화적 기여가 중요함을 인식했어요.","이것이 실현되는 출발점은 근대적 변혁이 초래할 '대도시'라는 환경이에요."]},{"kind":"points","head":"오른쪽 도식이 무엇인가요","items":["캡션은 '대도시 빈의 도시구조에 대한 바그너의 도식'이에요.","맨 위에 XXII. WIENER GEMEINDE-BEZIRK 라고 적혀 있어요. 빈의 22번째 구역이라는 뜻이에요.","네모난 블록이 바둑판처럼 줄지어 있고 가운데에 큰 녹지와 공공 건물이 있어요.","한 사람이 도시 전체를 이렇게 설계하려 했다는 점이 **오토 바그너(Otto Wagner)**의 스케일이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"바그너가 건축이 실현되는 출발점으로 본 환경은?","choices":["농촌 마을","근대적 변혁이 초래할 대도시","산업 공장"],"a":1,"why":"'대도시'라는 환경이에요. 근대 도시 생활의 실용예술이 건축이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["바그너는 **빈 분리파(Wiener Secession)** 경향을 보였지만 분리파 사람만은 아니에요.","'제체시온과 **아르 누보(Art Nouveau)** 경향을 보였음에도 합리적 기능주의자'가 정답 문장이에요."]}],"walk":{"head":null,"parts":[{"b":[0.04,0.11,0.9,0.11],"c":[0,0.065,0.99,0.2],"r":6.6,"img":"img/U3/walk/p018_22_01.jpg","say":"첫 항목. 제체시온과 아르 누보 경향에도 합리적 기능주의자의 길."},{"b":[0.04,0.23,0.9,0.11],"c":[0,0.185,0.99,0.2],"r":6.6,"img":"img/U3/walk/p018_22_02.jpg","say":"둘째 항목. 건축은 근대 도시 생활의 실용예술, 문화적 기여."},{"b":[0.04,0.35,0.9,0.05],"c":[0,0.275,0.99,0.2],"r":6.6,"img":"img/U3/walk/p018_22_03.jpg","say":"셋째 항목. 출발점은 근대적 변혁이 초래할 대도시라는 환경."},{"b":[0.01,0.5,0.41,0.39],"c":[0,0.4805,0.451,0.429],"r":1.4017,"img":"img/U3/walk/p018_22_04.jpg","say":"빈의 거리 사진. 꽃무늬 파사드 건물이 큰길에 붙어 서 있어요."},{"b":[0.43,0.5,0.55,0.42],"c":[0.395,0.479,0.605,0.462],"r":1.746,"img":"img/U3/walk/p018_22_05.jpg","say":"바그너의 도시구조 도식. 네모 블록이 바둑판처럼 줄지어 있어요."},{"b":[0.6,0.94,0.38,0.04],"c":[0.581,0.89,0.418,0.11],"r":5.0667,"img":"img/U3/walk/p018_22_06.jpg","say":"캡션. 대도시 빈의 도시구조에 대한 바그너의 도식."}]}},{"p":19,"title":"오토 바그너, 마욜리카하우스와 링케 빈 차일레 주거블록, 오스트리아 빈, 1898","terms":["마욜리카하우스","링케 빈 차일레","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 한 장에 건물 두 채가 나란히 찍혀 있어요.","왼쪽이 **마욜리카하우스**, 오른쪽이 **링케 빈 차일레**예요.","둘 다 **오토 바그너(Otto Wagner)**가 1898년 오스트리아 빈에 지은 주거블록이에요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자 **오토 바그너(Otto Wagner)**, 연도 1898년, 장소 오스트리아 빈이에요. 두 채가 이웃해 있어요.","왼쪽 **마욜리카하우스**: 벽 전체가 분홍 꽃과 초록 잎 타일로 덮여 있어요.","오른쪽 **링케 빈 차일레**: 벽이 희고 창 위에 금색 원판 장식이 붙어 있어요.","두 건물 모두 창의 크기와 층의 높이가 위아래로 똑같아요.","지붕 끝에는 사람 모양 청동 조각이 앉아 있어요.","무늬는 달라도 벽이 평평하고 창이 규칙적인 점은 똑같아요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마욜리카하우스**와 **링케 빈 차일레**는 몇 년 작품일까요?","choices":["1895","1898","1906"],"a":1,"why":"둘 다 1898년, 오스트리아 빈이에요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.42,0.88],"c":[0.029,0.006,0.462,0.968],"r":0.6364,"img":"img/U3/walk/p019_21_01.jpg","say":"**마욜리카하우스**. 분홍 꽃과 초록 잎 타일이 벽 전체를 덮어요."},{"b":[0.56,0.3,0.37,0.63],"c":[0.5415,0.2685,0.407,0.693],"r":0.7831,"img":"img/U3/walk/p019_21_02.jpg","say":"**링케 빈 차일레**. 흰 벽에 금색 원판과 늘어진 장식이 붙어 있어요."},{"b":[0.52,0.22,0.1,0.12],"c":[0.47,0.204,0.2,0.152],"r":1.7544,"img":"img/U3/walk/p019_21_03.jpg","say":"지붕 위에 앉은 청동 조각이에요."},{"b":[0.06,0.12,0.4,0.3],"c":[0.04,0.104,0.44,0.332],"r":1.7671,"img":"img/U3/walk/p019_21_04.jpg","say":"창을 봐요. 크기와 간격, 층 높이가 위아래로 같아요."},{"b":[0.3,0.95,0.6,0.04],"c":[0.27,0.8667,0.66,0.1333],"r":6.6017,"img":"img/U3/walk/p019_21_05.jpg","say":"캡션. 오토 바그너, 마욜리카하우스와 링케 빈 차일레 주거블록, 1898."}]}},{"p":20,"title":"마욜리카하우스 & 링케 빈 차일레: 각 층 평준화와 표면이 구조와 분리","terms":["각 층 평준화","마욜리카하우스","링케 빈 차일레","ornament","decoration"],"pass1":[{"kind":"say","lines":["이 쪽이 두 주거블록에서 가장 중요한 내용이에요.","층마다 높이를 똑같이 맞췄어요. 이것을 **각 층 평준화**라고 해요.","그리고 벽의 겉면이 구조와 따로 놀아요. 겉면은 붙인 마감재일 뿐이에요."]},{"kind":"analogy","head":"벽은 케이크가 아니라 포장지","scene":"옛날 벽은 돌을 파서 조각한 케이크였고, 바그너의 벽은 무늬를 인쇄한 포장지예요.","map":[["조각한 케이크","벽 자체가 조각으로 기능하는 바로크식 **장식물(ornament)**"],["붙인 포장지","밋밋한 벽에 2차원 마감재를 덧입히는 **치장(decoration)**"],["그 결과","파사드에서 표면이 구조와 분리돼요"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**각 층 평준화**: 엘리베이터 덕분에 층마다 층고를 똑같이 산정한 구성이에요.","**장식물(ornament)**: 벽 자체가 조각처럼 기능하는 바로크식 입체 장식이에요.","**치장(decoration)**: 밋밋한 벽에 2차원 마감재를 덧입히는 면 처리예요.","파사드는 건물의 얼굴, 즉 길에서 보이는 정면 벽을 말해요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["각 층의 층고는 동일하게 산정해요.","즉 엘리베이터는 적층의 구성을 보다 동등하도록 하는 데 결정적 역할을 했어요.","각 층은 평준화돼요.","벽감을 지닌 무거운 벽과 대조적인 평평한 형태로서의 벽, 즉 장식보다는 기능을 나타내는 벽이에요.","벽 자체가 조각으로서 기능하는 바로크적 접근이 아니라 밋밋한 벽에 2차원의 마감재를 덧입히는 방식이에요.","파사드에서 그 표면이 구조와 분리돼요."]},{"kind":"look","walked":1},{"kind":"compare","head":"엘리베이터가 없던 시절과 있는 시절","cols":["항목","옛 건물","바그너의 주거블록"],"rows":[["층고","아래층이 높고 위로 갈수록 낮아요","**각 층 평준화**, 층고가 같아요"],["벽","파서 조각하는 **장식물(ornament)**","붙이는 **치장(decoration)**"],["표면과 구조","한 덩어리예요","표면이 구조와 분리돼요"]]}],"pass3":[{"kind":"check","q":"**마욜리카하우스**에서 각 층을 평준화하는 데 결정적 역할을 한 것은?","choices":["엘리베이터","철골 구조","유리 커튼월"],"a":0,"why":"엘리베이터가 적층의 구성을 동등하게 만들었어요."},{"kind":"check","q":"**마욜리카하우스** 파사드의 벽 처리 방식은?","choices":["벽 자체가 조각으로 기능하는 바로크적 접근","밋밋한 벽에 2차원 마감재를 덧입히고 표면이 구조와 분리","구조체를 그대로 노출"],"a":1,"why":"바로크적 접근이 아니라 2차원 마감재를 덧입히는 방식이에요."},{"kind":"english","head":"논술 답안: 마욜리카하우스와 링케 빈 차일레","en":"오토 바그너가 1898년 빈에 지은 마욜리카하우스와 링케 빈 차일레 주거블록은 각 층의 층고를 동일하게 산정하였으며, 엘리베이터가 적층 구성을 동등하게 하는 데 결정적 역할을 하였다.","ko":"벽감을 지닌 무거운 벽과 대조적으로 평평한 벽을 썼고, 밋밋한 벽에 이차원의 마감재를 덧입혀 파사드에서 표면이 구조와 분리되었다.","tip":"'층고 동일 + 엘리베이터 + 평평한 벽 + 표면과 구조의 분리' 네 개를 쓰면 돼요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.32,0.05],"c":[0.034,0.05,0.352,0.11],"r":4.2667,"img":"img/U3/walk/p020_22_01.jpg","say":"제목. 마욜리카하우스 & 링케 빈 차일레 주거블록."},{"b":[0.05,0.17,0.45,0.24],"c":[0.0275,0.154,0.495,0.272],"r":2.4265,"img":"img/U3/walk/p020_22_02.jpg","say":"앞 세 항목. 층고 동일, 엘리베이터의 결정적 역할, 각 층 평준화."},{"b":[0.05,0.41,0.45,0.38],"c":[0.0275,0.391,0.495,0.418],"r":1.5789,"img":"img/U3/walk/p020_22_03.jpg","say":"뒤 세 항목. 평평한 벽, 2차원 마감재, 표면이 구조와 분리."},{"b":[0.55,0.03,0.43,0.44],"c":[0.527,0.008,0.473,0.484],"r":1.303,"img":"img/U3/walk/p020_22_04.jpg","say":"두 주거블록의 평면도예요. 두 덩어리가 비스듬히 붙어 있어요."},{"b":[0.5,0.49,0.48,0.48],"c":[0.472,0.466,0.528,0.528],"r":1.3333,"img":"img/U3/walk/p020_22_05.jpg","say":"거리 사진. 두 건물의 층 높이가 나란히 맞아 있어요."}]}},{"p":21,"title":"마욜리카하우스: 식물 문양 타일과 위생, 오스트리아 빈, 1898","terms":["마욜리카하우스","Otto Wagner"],"pass1":[{"kind":"say","lines":["이 쪽은 **마욜리카하우스**의 타일 이야기예요.","꽃무늬가 예뻐서 붙인 것이 아니라 비바람에 강하고 씻기 쉬워서 골랐어요.","근대 사회에서 가장 중요한 것이 '위생'이었기 때문이에요."]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["**마욜리카하우스**의 식물 문양 타일은 풍화에 잘 견디고 유지관리가 수월하며 세척도 편한 재료예요.","**오토 바그너(Otto Wagner)**는 이런 신재료가 주는 혜택을 마음껏 누리고자 했어요.","근대사회에서 무엇보다 중요한 '위생'에 대한 고려가 있었어요.","그 고려가 재료의 선택, 그리고 파사드의 장식 및 시공 방식의 일대 전환으로 이어졌어요."]},{"kind":"points","head":"이 사진에서 볼 것","items":["분홍 꽃과 초록 잎, 가는 줄기가 벽 전체에 이어져 있어요.","무늬는 곡선인데 벽 자체는 완전히 평평해요. 튀어나온 조각이 하나도 없어요.","창은 크기와 간격이 모두 같고, 창틀 장식도 거의 없어요.","타일이라서 비가 와도 씻겨 내려가고 걸레로 닦을 수도 있어요.","곡선 무늬는 남아 있지만 붙이는 방식은 이미 근대적이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**마욜리카하우스** 타일을 고른 근대적인 이유는?","choices":["값이 가장 쌌어요","풍화에 강하고 유지관리와 세척이 쉬워 위생에 좋았어요","황제가 좋아했어요"],"a":1,"why":"위생에 대한 고려가 재료 선택과 시공 방식의 전환으로 이어졌어요."},{"kind":"english","head":"논술 답안: 마욜리카하우스의 타일","en":"마욜리카하우스에 사용된 식물 문양의 타일은 풍화에 잘 견디고 유지관리가 수월하며 세척도 편한 재료로, 바그너는 이러한 신재료의 혜택을 누리고자 하였다.","ko":"근대사회에서 무엇보다 중요한 위생에 대한 고려는 재료의 선택과 파사드의 장식 및 시공 방식의 일대 전환으로 이어졌다.","tip":"'풍화, 유지관리, 세척 → 위생 → 시공 방식의 전환' 흐름으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.02,0.2,0.04],"c":[0.058,0,0.224,0.11],"r":2.7152,"img":"img/U3/walk/p021_22_01.jpg","say":"제목. 마욜리카하우스."},{"b":[0.06,0.06,0.88,0.28],"c":[0.016,0.044,0.968,0.312],"r":4.1368,"img":"img/U3/walk/p021_22_02.jpg","say":"세 항목. 풍화, 유지관리, 세척, 신재료의 혜택, 위생."},{"b":[0.17,0.35,0.62,0.55],"c":[0.139,0.3225,0.682,0.605],"r":1.503,"img":"img/U3/walk/p021_22_03.jpg","say":"타일 파사드 사진. 분홍 꽃과 초록 잎이 벽을 덮어요."},{"b":[0.2,0.38,0.25,0.2],"c":[0.1875,0.364,0.275,0.232],"r":1.5805,"img":"img/U3/walk/p021_22_04.jpg","say":"창 위에 붙은 금색 장식과 검은 받침이에요."},{"b":[0.28,0.95,0.45,0.04],"c":[0.2575,0.89,0.495,0.11],"r":6.0,"img":"img/U3/walk/p021_22_05.jpg","say":"캡션. 오토 바그너, 마욜리카하우스, 오스트리아 빈, 1898."}]}},{"p":22,"title":"쇠 장식과 엘리베이터 (캡션 없는 쪽)","terms":["마욜리카하우스","링케 빈 차일레"],"pass1":[{"kind":"say","lines":["글자가 하나도 없는 사진 두 장이에요.","건물 안의 엘리베이터와 그 둘레의 쇠 장식이 보여요.","앞뒤 쪽이 **마욜리카하우스**와 **링케 빈 차일레**라서 그 주변 사진으로 읽으면 돼요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에는 캡션이 없어요. 건물 이름과 연도가 글로 적혀 있지 않아요.","왼쪽: 엘리베이터 앞을 막은 쇠 울타리예요. 흰 쇠를 구부려 꽃과 덩굴 모양을 만들었어요.","울타리 가운데에 붉은 동그라미들이 박혀 있어요.","오른쪽: 엘리베이터 칸이에요. 붉은 나무통에 금색 띠를 두르고 구멍을 뚫었어요.","엘리베이터 뒤로 계단의 흰 난간이 곡선으로 휘어져 올라가요."]},{"kind":"points","head":"이 사진이 왜 여기 있을까요","items":["앞 쪽에서 엘리베이터가 **각 층 평준화**를 가능하게 했다고 배웠어요.","그 엘리베이터의 실물이 이렇게 생겼다는 것을 보여 주는 쪽이에요.","쇠 장식은 곡선이지만 얇은 판을 잘라 붙인 방식이에요.","즉 벽을 파서 만든 장식이 아니라 붙인 장식이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.05,0.15,0.41,0.8],"c":[0.0295,0.11,0.451,0.88],"r":0.6833,"img":"img/U3/walk/p022_22_01.jpg","say":"엘리베이터 앞 쇠 울타리. 흰 쇠로 만든 꽃과 덩굴 모양이에요."},{"b":[0.14,0.36,0.32,0.22],"c":[0.124,0.344,0.352,0.252],"r":1.8624,"img":"img/U3/walk/p022_22_02.jpg","say":"붉은 동그라미가 박힌 부분을 자세히 봐요."},{"b":[0.52,0.16,0.46,0.79],"c":[0.494,0.1205,0.506,0.869],"r":0.7764,"img":"img/U3/walk/p022_22_03.jpg","say":"엘리베이터 칸. 붉은 나무통에 금색 띠를 둘렀어요."},{"b":[0.63,0.38,0.3,0.28],"c":[0.615,0.364,0.33,0.312],"r":1.4103,"img":"img/U3/walk/p022_22_04.jpg","say":"금색 띠에 구멍을 뚫어 무늬를 만들었어요."}]}},{"p":23,"title":"창살과 계단 난간 (캡션 없는 쪽)","terms":["마욜리카하우스","링케 빈 차일레"],"pass1":[{"kind":"say","lines":["역시 글자가 없는 사진 두 장이에요.","왼쪽은 창 앞의 쇠 창살, 오른쪽은 계단 난간이에요.","**마욜리카하우스**와 **링케 빈 차일레** 이야기 사이에 놓인 쪽이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에도 캡션이 없어서 건물 이름을 단정할 수 없어요.","왼쪽: 창 앞에 세로 쇠막대가 촘촘히 서 있고, 아래쪽에 꽃 모양 쇠판이 붙어 있어요.","막대 중간에는 작은 튤립 모양 장식이 한 줄로 달려 있어요.","오른쪽: 계단을 따라 곡선으로 휘어 올라가는 난간이에요.","연한 초록색 쇠판을 꽃과 잎 모양으로 오려 붙였고, 손잡이는 나무예요.","붉은 동그라미 몇 개가 꽃 속에 박혀 있어요."]},{"kind":"points","head":"무엇을 눈에 담아야 할까요","items":["장식이 전부 '오려서 붙인 판'이에요. 깎아 만든 덩어리가 아니에요.","이것이 앞 쪽에서 말한 **치장(decoration)** 방식이에요.","**오토 바그너(Otto Wagner)**의 건물은 이렇게 난간과 창살까지 같은 어휘로 맞춰져 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.05,0.11,0.46,0.81],"c":[0.027,0.0695,0.506,0.891],"r":0.7572,"img":"img/U3/walk/p023_22_01.jpg","say":"창 앞 쇠 창살. 세로 막대와 꽃 모양 쇠판이 보여요."},{"b":[0.07,0.6,0.4,0.28],"c":[0.05,0.584,0.44,0.312],"r":1.8803,"img":"img/U3/walk/p023_22_02.jpg","say":"아래쪽 꽃 모양 쇠판을 자세히 봐요."},{"b":[0.53,0.11,0.46,0.84],"c":[0.494,0.068,0.506,0.924],"r":0.7302,"img":"img/U3/walk/p023_22_03.jpg","say":"계단 난간. 초록 쇠판을 꽃과 잎 모양으로 오려 붙였어요."},{"b":[0.56,0.4,0.36,0.35],"c":[0.542,0.3825,0.396,0.385],"r":1.3714,"img":"img/U3/walk/p023_22_04.jpg","say":"붉은 동그라미가 꽃 속에 박혀 있어요."}]}},{"p":24,"title":"현관 복도와 출입문 (캡션 없는 쪽, 문패에 Kostlergasse 1)","terms":["링케 빈 차일레","마욜리카하우스"],"pass1":[{"kind":"say","lines":["글자가 없는 사진 세 장이에요. 건물의 현관이에요.","오른쪽 아래 문 위 문패에 숫자 1과 거리 이름이 보여요.","뒤쪽 27번 슬라이드에도 같은 거리 이름이 새겨진 사진이 나와요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에는 캡션이 없어요. 그래서 이름을 단정하지 않고 보이는 것만 적을게요.","왼쪽: 현관 복도예요. 흰 벽과 둥근 천장, 바닥에는 검은 띠무늬 타일이 깔려 있어요.","복도 끝에 쇠 울타리로 막은 문이 있어요. 앞 쪽에서 본 엘리베이터 울타리와 비슷해요.","오른쪽 위: 천장에 붙은 등이에요. 둥근 유리구 뒤에 연초록 잎 모양 판을 받쳤어요.","오른쪽 아래: 출입문이에요. 짙은 회색 문에 잎사귀 모양 쇠 장식이 붙어 있어요.","문 위 둥근 문패에 숫자 1과 Kostlergasse 라는 거리 이름이 보여요."]},{"kind":"points","head":"어디에 연결되나요","items":["뒤에 나오는 **링케 빈 차일레** 사진에도 같은 거리 이름과 번지가 벽에 새겨져 있어요.","그래서 이 현관 사진들은 **마욜리카하우스**와 **링케 빈 차일레** 이야기의 사이에 놓여 있어요.","다만 슬라이드가 이름을 적지 않았으니 시험에는 이 쪽 자체가 나오기 어려워요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.02,0.19,0.42,0.79],"c":[0,0.131,0.462,0.869],"r":0.7089,"img":"img/U3/walk/p024_22_01.jpg","say":"현관 복도. 흰 벽, 둥근 천장, 검은 띠무늬 바닥 타일이에요."},{"b":[0.17,0.44,0.15,0.22],"c":[0.145,0.424,0.2,0.252],"r":1.0582,"img":"img/U3/walk/p024_22_02.jpg","say":"복도 끝의 쇠 울타리 문이에요."},{"b":[0.68,0.07,0.31,0.37],"c":[0.659,0.0515,0.341,0.407],"r":1.1171,"img":"img/U3/walk/p024_22_03.jpg","say":"천장 등. 유리구 뒤에 연초록 잎 모양 판이 있어요."},{"b":[0.49,0.48,0.5,0.5],"c":[0.45,0.45,0.55,0.55],"r":1.3333,"img":"img/U3/walk/p024_22_04.jpg","say":"출입문. 잎사귀 모양 쇠 장식이 붙어 있어요."},{"b":[0.68,0.5,0.11,0.06],"c":[0.635,0.475,0.2,0.11],"r":2.4242,"img":"img/U3/walk/p024_22_05.jpg","say":"문 위 문패. 숫자 1과 거리 이름이 보여요."}]}},{"p":25,"title":"링케 빈 차일레: 매끈한 형태와 저층부 수평 띠","terms":["링케 빈 차일레","Otto Wagner"],"pass1":[{"kind":"say","lines":["이 쪽은 **링케 빈 차일레**의 특징 두 가지를 말해요.","첫째, 쭉 뻗은 큰길에 접하는 매끈하고 정형적인 형태예요.","둘째, 저층부에 수평 띠를 양각으로 새겨서 투시도 효과를 극대화했어요."]},{"kind":"analogy","head":"수평 띠는 달리는 줄무늬","scene":"차창 밖으로 지나가는 줄무늬 담장처럼, 띠가 시선을 길 끝까지 끌고 가요.","map":[["쭉 뻗은 큰길","근대 대도시의 스펙터클한 가로"],["길을 따라 흐르는 줄무늬","저층부에 양각으로 새긴 수평 띠"],["멀리까지 빨려 드는 느낌","투시도적 효과의 극대화"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["**링케 빈 차일레**는 근대 대도시의 쭉 뻗은 스펙터클한 가로에 접하는 매끈하고 정형적인 형태의 건물이에요.","저층부에 양각으로 수평 띠를 새겨 넣음으로써 투시도적 효과를 극대화했어요.","양각은 바탕보다 도드라지게 새기는 것이고, 투시도적 효과는 멀어질수록 좁아 보이는 효과예요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽: 길모퉁이에서 본 전체예요. 모서리가 둥글게 말려 있고 1층은 유리로 뚫려 있어요.","벽이 희고 평평해서 창이 격자처럼 가지런히 보여요.","오른쪽: 발코니 층을 가까이 찍었어요. 가로로 길게 이어진 난간이 띠처럼 보여요.","이 가로 띠가 시선을 길 방향으로 쭉 끌어 줘요.","**오토 바그너(Otto Wagner)**가 말한 대도시의 건축이 이런 모습이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**링케 빈 차일레** 저층부의 처리 방식과 목적은?","choices":["양각 수평 띠로 투시도적 효과 극대화","오목한 벽감으로 그늘 만들기","유리 커튼월로 개방감 주기"],"a":0,"why":"저층부에 양각으로 수평 띠를 새겨 투시도적 효과를 극대화했어요."},{"kind":"english","head":"논술 답안: 링케 빈 차일레","en":"링케 빈 차일레는 오토 바그너가 1898년 빈에 지은 주거블록으로, 근대 대도시의 쭉 뻗은 스펙터클한 가로에 접하는 매끈하고 정형적인 형태를 가진다.","ko":"저층부에는 양각으로 수평 띠를 새겨 넣어 투시도적 효과를 극대화하였다.","tip":"'매끈하고 정형적 + 저층부 수평 띠 + 투시도 효과' 세 개면 충분해요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.08,0.15,0.04],"c":[0.035,0.045,0.2,0.11],"r":2.4242,"img":"img/U3/walk/p025_22_01.jpg","say":"제목. 링케 빈 차일레."},{"b":[0.02,0.25,0.47,0.46],"c":[0,0.227,0.517,0.506],"r":1.3623,"img":"img/U3/walk/p025_22_02.jpg","say":"길모퉁이에서 본 전체. 매끈하고 정형적인 형태예요."},{"b":[0.5,0.25,0.49,0.46],"c":[0.461,0.227,0.539,0.506],"r":1.4203,"img":"img/U3/walk/p025_22_03.jpg","say":"발코니 층 확대. 가로로 길게 이어진 난간이 띠를 이뤄요."},{"b":[0.06,0.79,0.88,0.05],"c":[0.016,0.7172,0.968,0.1956],"r":6.5985,"img":"img/U3/walk/p025_22_04.jpg","say":"첫 항목. 쭉 뻗은 가로에 접하는 매끈하고 정형적인 형태."},{"b":[0.06,0.85,0.88,0.05],"c":[0.016,0.7772,0.968,0.1956],"r":6.5985,"img":"img/U3/walk/p025_22_05.jpg","say":"둘째 항목. 저층부 양각 수평 띠로 투시도적 효과 극대화."}]}},{"p":26,"title":"오토 바그너, 링케 빈 차일레, 오스트리아 빈, 1898 (모퉁이 전경)","terms":["링케 빈 차일레","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **링케 빈 차일레**의 모퉁이를 올려다본 모습이에요.","**오토 바그너(Otto Wagner)**, 오스트리아 빈, 1898년이에요.","모서리가 둥글게 말려 있고 꼭대기에 청동 조각이 앉아 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["모서리가 각지지 않고 둥글게 휘어 있어요. 길이 꺾이는 자리를 부드럽게 돌아요.","꼭대기 양쪽에 청동 사람 조각이 앉아 있어요.","창 사이마다 금색 원판과 아래로 늘어진 장식이 붙어 있어요.","벽 자체는 완전히 평평하고, 장식은 그 위에 얇게 붙어 있어요.","창의 크기와 층의 높이가 위아래로 같아요. **각 층 평준화**가 눈에 보여요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.08,0.05,0.84,0.9],"c":[0.038,0.005,0.924,0.99],"r":1.2444,"img":"img/U3/walk/p026_21_01.jpg","say":"사진 전체. 링케 빈 차일레의 모퉁이 전경이에요."},{"b":[0.31,0.08,0.34,0.2],"c":[0.293,0.064,0.374,0.232],"r":2.1494,"img":"img/U3/walk/p026_21_02.jpg","say":"둥글게 말린 모서리와 그 위 청동 조각이에요."},{"b":[0.09,0.33,0.22,0.3],"c":[0.078,0.314,0.244,0.332],"r":0.9799,"img":"img/U3/walk/p026_21_03.jpg","say":"금색 원판과 늘어진 장식이 창 사이에 붙어 있어요."},{"b":[0.33,0.45,0.3,0.35],"c":[0.315,0.4325,0.33,0.385],"r":1.1429,"img":"img/U3/walk/p026_21_04.jpg","say":"창의 크기와 층 높이가 위아래로 같아요."},{"b":[0.3,0.95,0.58,0.04],"c":[0.271,0.8711,0.638,0.1289],"r":6.5994,"img":"img/U3/walk/p026_21_05.jpg","say":"캡션. 오토 바그너, 링케 빈 차일레, 오스트리아 빈, 1898."}]}},{"p":27,"title":"링케 빈 차일레의 현관과 금색 원판 장식","terms":["링케 빈 차일레","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 세 장 모두 **링케 빈 차일레**예요.","왼쪽 위 현관 위에 KOSTLERGASSE 1, LINKE WIENZEILE No 38 이라 새겨져 있어요.","건물 이름이 곧 주소라는 것을 확인할 수 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 현관이에요. 문 위에 주소가 금색 대문자로 새겨져 있고 양옆에 금색 월계수 고리가 있어요.","왼쪽 아래: 벽면 확대예요. 금색 원판과 아래로 길게 늘어진 장식이 창 사이에 붙어 있어요.","늘어진 장식은 벽에서 거의 튀어나오지 않고 얇게 붙어 있어요.","오른쪽: 길 건너에서 본 전체예요. 1층과 2층이 유리로 길게 뚫려 있어요.","캡션은 오토 바그너, **링케 빈 차일레**, 오스트리아 빈, 1898이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.04,0.45,0.44],"c":[0.0075,0.018,0.495,0.484],"r":1.3636,"img":"img/U3/walk/p027_21_01.jpg","say":"현관. 문 위에 주소가 금색 대문자로 새겨져 있어요."},{"b":[0.05,0.19,0.3,0.1],"c":[0.035,0.174,0.33,0.132],"r":3.3333,"img":"img/U3/walk/p027_21_02.jpg","say":"KOSTLERGASSE 1, LINKE WIENZEILE No 38 이라는 글씨예요."},{"b":[0.02,0.5,0.45,0.45],"c":[0,0.4775,0.495,0.495],"r":1.3333,"img":"img/U3/walk/p027_21_03.jpg","say":"벽면 확대. 금색 원판과 늘어진 장식이에요."},{"b":[0.5,0.28,0.48,0.49],"c":[0.472,0.2555,0.528,0.539],"r":1.3061,"img":"img/U3/walk/p027_21_04.jpg","say":"길 건너에서 본 전체. 저층부가 유리로 길게 뚫려 있어요."},{"b":[0.51,0.8,0.38,0.03],"c":[0.491,0.76,0.418,0.11],"r":5.0667,"img":"img/U3/walk/p027_21_05.jpg","say":"캡션. 오토 바그너, 링케 빈 차일레, 오스트리아 빈, 1898."}]}},{"p":28,"title":"오토 바그너, 우편저축은행, 오스트리아 빈, 1906 (메인 뱅킹 룸)","terms":["우편저축은행","Otto Wagner","배럴 보울트 지붕"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **우편저축은행**의 메인 뱅킹 룸이에요.","**오토 바그너(Otto Wagner)**가 1906년 오스트리아 빈에 지었어요.","'최초의 진정한 근대 인테리어'라고 불리는 공간이에요."]},{"kind":"say","lines":["주문을 다시 외워요. 싫어 → 새 장식 → 정리 → 없애.","여기가 바로 '없애'에 아주 가까워진 자리예요.","장식이 거의 없고 구조와 빛만 남았어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["설계자 **오토 바그너(Otto Wagner)**, 연도 1906년, 장소 오스트리아 빈이에요.","천장이 둥근 터널처럼 휘어 있어요. 이것이 **배럴 보울트 지붕**이에요.","천장은 가는 철골 격자와 유리로만 이뤄져 있어요. 빛이 그대로 들어와요.","바닥에도 유리 블록이 깔려 있어서 회색으로 반짝여요.","은은한 기둥은 금속이고 표면에 볼트 머리가 줄지어 박혀 있어요.","벽에는 무늬가 없고 창구 번호판과 시계만 붙어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**우편저축은행**은 언제, 누가 지었을까요?","choices":["1898년 올브리히","1906년 **오토 바그너(Otto Wagner)**","1912년 로스"],"a":1,"why":"오토 바그너, 오스트리아 빈, 1906년이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**우편저축은행**은 1906년이에요. 1898년이라고 하면 틀려요. 1898년은 마욜리카하우스와 링케 빈 차일레예요."]}],"walk":{"head":null,"parts":[{"b":[0.08,0.05,0.22,0.04],"c":[0.068,0.015,0.244,0.11],"r":2.9576,"img":"img/U3/walk/p028_21_01.jpg","say":"제목. 비엔나 우편저축은행."},{"b":[0.09,0.11,0.81,0.34],"c":[0.0495,0.093,0.891,0.374],"r":3.1765,"img":"img/U3/walk/p028_21_02.jpg","say":"**배럴 보울트 지붕**. 철골 격자와 유리로 된 둥근 천장이에요."},{"b":[0.15,0.58,0.12,0.22],"c":[0.11,0.564,0.2,0.252],"r":1.0582,"img":"img/U3/walk/p028_21_03.jpg","say":"금속 기둥. 표면에 볼트 머리가 줄지어 박혀 있어요."},{"b":[0.3,0.28,0.4,0.18],"c":[0.28,0.264,0.44,0.212],"r":2.7673,"img":"img/U3/walk/p028_21_04.jpg","say":"가운데 아치 창. 벽에 장식이 하나도 없어요."},{"b":[0.14,0.78,0.72,0.16],"c":[0.104,0.764,0.792,0.192],"r":5.5,"img":"img/U3/walk/p028_21_05.jpg","say":"바닥. 유리 블록이 깔려 회색으로 반짝여요."},{"b":[0.46,0.96,0.44,0.03],"c":[0.438,0.89,0.484,0.11],"r":5.8667,"img":"img/U3/walk/p028_21_06.jpg","say":"캡션. 오토 바그너, 우편 저축은행, 오스트리아 빈, 1906."}]}},{"p":29,"title":"우편저축은행의 외관과 평면 (캡션 없는 쪽, 벽에 OSTERR. POSTSPARKASSE)","terms":["우편저축은행"],"pass1":[{"kind":"say","lines":["사진 두 장과 평면도 한 장이에요. 캡션 글은 없어요.","오른쪽 위 건물 벽에 OSTERR. POSTSPARKASSE 라고 새겨져 있어요.","앞 쪽에서 본 **우편저축은행**의 바깥 모습이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것을 적어요","items":["왼쪽: 길모퉁이에서 본 전체예요. 벽이 흰 판으로 덮여 있고 그 위에 볼트 머리가 점점이 박혀 있어요.","돌을 쌓은 벽이 아니라 얇은 판을 볼트로 고정한 벽이에요.","창은 크기와 간격이 모두 같고 창틀 장식이 거의 없어요.","오른쪽 위: 정면이에요. 벽 위쪽에 OSTERR. POSTSPARKASSE 라는 글씨가 있어요.","지붕 난간 위에 금속 조각상들이 줄지어 서 있어요.","오른쪽 아래: 평면도예요. 사다리꼴 대지 안에 사각형 방들이 둘러싸고 가운데가 뚫려 있어요."]},{"kind":"points","head":"무엇을 봐야 할까요","items":["가운데 뚫린 곳이 앞 쪽에서 본 메인 뱅킹 룸이에요.","벽의 볼트 머리는 숨기지 않고 그대로 드러낸 고정 장치예요.","**우편저축은행**은 겉에서도 '붙인 판'과 '고정한 볼트'가 그대로 보여요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.09,0.45,0.81],"c":[0.0075,0.0495,0.495,0.891],"r":0.7407,"img":"img/U3/walk/p029_22_01.jpg","say":"길모퉁이에서 본 전체. 흰 판 벽에 볼트 머리가 점점이 박혀 있어요."},{"b":[0.05,0.25,0.25,0.25],"c":[0.0375,0.234,0.275,0.282],"r":1.3002,"img":"img/U3/walk/p029_22_02.jpg","say":"벽면 확대. 판과 볼트 머리가 규칙적으로 보여요."},{"b":[0.5,0.03,0.47,0.44],"c":[0.4765,0.008,0.517,0.484],"r":1.4242,"img":"img/U3/walk/p029_22_03.jpg","say":"정면. 벽 위쪽에 OSTERR. POSTSPARKASSE 글씨가 있어요."},{"b":[0.61,0.13,0.2,0.04],"c":[0.598,0.095,0.224,0.11],"r":2.7152,"img":"img/U3/walk/p029_22_04.jpg","say":"그 글씨 부분이에요. 건물 이름이 벽에 새겨져 있어요."},{"b":[0.5,0.49,0.48,0.45],"c":[0.472,0.4675,0.528,0.495],"r":1.4222,"img":"img/U3/walk/p029_22_05.jpg","say":"평면도. 사다리꼴 대지 안 가운데가 뚫려 있어요."},{"b":[0.66,0.6,0.18,0.2],"c":[0.648,0.584,0.204,0.232],"r":1.1724,"img":"img/U3/walk/p029_22_06.jpg","say":"가운데 뚫린 곳이 메인 뱅킹 룸이에요."}]}},{"p":30,"title":"우편저축은행: 배럴 보울트 지붕, 리벳, 구조용 유리 바닥","terms":["우편저축은행","배럴 보울트 지붕","구조용 유리 바닥","Otto Wagner"],"pass1":[{"kind":"say","lines":["이 쪽이 **우편저축은행**의 시험 포인트예요.","지붕은 **배럴 보울트 지붕**, 바닥은 **구조용 유리 바닥**이에요.","철제 기둥의 리벳은 장식처럼 쓰였어요."]},{"kind":"analogy","head":"장식을 없애고 남은 것","scene":"볼트 머리를 숨기지 않고 그대로 보여 주는 것이 장식이 됐어요.","map":[["옛 건물의 꽃무늬 조각","없앴어요"],["남은 장식","철제 기둥의 리벳 머리"],["남은 무늬","바닥 타일의 검은색과 흰색 띠 몇 개"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**배럴 보울트 지붕**: 술통을 반으로 자른 듯 둥근 터널 모양의 지붕이에요.","여기서는 노출된 메탈 구조와 유리로 만들었어요.","**구조용 유리 바닥**: 빛이 지하로 투과하도록 유리로 만든 바닥이에요.","리벳은 금속판을 잇는 굵은 못 같은 것이에요. 머리가 동그랗게 튀어나와요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["은행의 주 업무실엔 노출된 메탈 구조와 유리로 만들어진 **배럴 보울트 지붕**을 썼어요.","철제기둥의 리벳들은 장식적인 요소처럼 쓰여요.","그 밖의 장식 디테일은 바닥 타일에 있는 몇 개의 검은색과 흰색 띠에 한정되어 있어요.","바닥은 대부분 **구조용 유리 바닥**이라서 빛이 지하로 투과해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**우편저축은행** 주 업무실 지붕의 형식은?","choices":["콘크리트 돔","노출 메탈 구조와 유리의 **배럴 보울트 지붕**","목조 박공 지붕"],"a":1,"why":"노출된 메탈 구조와 유리로 만든 배럴 보울트 지붕이에요."},{"kind":"check","q":"**우편저축은행** 바닥이 대부분 **구조용 유리 바닥**인 이유는?","choices":["미끄럼 방지","빛이 지하로 투과하게 하려고","값이 싸서"],"a":1,"why":"빛이 지하로 투과하도록 유리로 만들었어요."},{"kind":"check","q":"**우편저축은행**에서 장식적 요소처럼 쓰인 것은?","choices":["철제기둥의 리벳","금박 몰딩","대리석 조각"],"a":0,"why":"리벳 머리가 장식처럼 쓰였고 나머지 장식은 바닥 타일의 검은색과 흰색 띠뿐이에요."},{"kind":"english","head":"논술 답안: 빈 우편저축은행의 구조","en":"빈 우편저축은행의 주 업무실에는 노출된 메탈 구조와 유리로 만들어진 배럴 보울트 지붕을 사용하였고, 철제기둥의 리벳들이 장식적인 요소처럼 쓰였다.","ko":"그 밖의 장식 디테일은 바닥 타일의 몇 개의 검은색과 흰색 띠에 한정되며, 바닥은 대부분 구조용 유리로 되어 있어 빛이 지하로 투과한다.","tip":"'배럴 보울트 + 리벳 + 검은색 흰색 띠 + 구조용 유리 바닥' 네 개를 외워요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.1,0.88,0.2],"c":[0.016,0.084,0.968,0.232],"r":5.5632,"img":"img/U3/walk/p030_22_01.jpg","say":"세 항목. 배럴 보울트 지붕, 리벳, 구조용 유리 바닥이에요."},{"b":[0.02,0.39,0.49,0.48],"c":[0,0.366,0.539,0.528],"r":1.3611,"img":"img/U3/walk/p030_22_02.jpg","say":"천장을 올려다본 사진. 철골 격자와 유리로 된 둥근 터널이에요."},{"b":[0.05,0.42,0.42,0.2],"c":[0.029,0.404,0.462,0.232],"r":2.6552,"img":"img/U3/walk/p030_22_03.jpg","say":"격자 하나하나가 유리예요. 빛이 그대로 들어와요."},{"b":[0.52,0.39,0.47,0.48],"c":[0.483,0.366,0.517,0.528],"r":1.3056,"img":"img/U3/walk/p030_22_04.jpg","say":"업무실 바닥. 유리 블록과 검은색 띠 몇 개만 보여요."},{"b":[0.56,0.65,0.4,0.2],"c":[0.54,0.634,0.44,0.232],"r":2.5287,"img":"img/U3/walk/p030_22_05.jpg","say":"바닥의 검은색과 흰색 띠. 남은 장식이 이것뿐이에요."}]}},{"p":31,"title":"우편저축은행: 네이브와 아일, 리벳, 최초의 진정한 근대 인테리어","terms":["우편저축은행","네이브와 아일","배럴 보울트 지붕","구조용 유리 바닥","Otto Wagner"],"pass1":[{"kind":"say","lines":["이 쪽이 **우편저축은행**의 결론이에요.","가운데가 높고 양옆이 낮은 구성을 **네이브와 아일**이라고 해요.","그리고 이 공간을 '최초의 진정한 근대 인테리어'라고 불러요."]},{"kind":"analogy","head":"네이브와 아일은 교회 본당의 모양","scene":"가운데 통로가 높고 양옆 복도가 낮은 교회 본당의 단면을 떠올려요.","map":[["교회의 높은 가운데","층고가 높은 중앙 부분"],["교회의 낮은 양옆","더 낮은 측면 공간들"],["다른 점","돌기둥이 아니라 리벳이 노출된 금속 기둥이에요"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**네이브와 아일**: 가운데가 높고 양옆이 낮은 세 갈래 공간 구성이에요.","원래 교회 본당의 구성인데 **우편저축은행**이 그것을 근대적인 방식으로 다시 썼어요.","인테리어는 건물 안쪽의 공간과 마감 전체를 말해요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["중앙의 메인 뱅킹 룸은 층고가 높은 중앙 부분과 양쪽으로 더 낮은 측면 공간들로 구성돼요.","이것이 완전히 근대적인 방식의 **네이브와 아일**이에요.","지지 기둥들은 리벳의 머리들이 노출된 금속이에요.","**우편저축은행**은 최초의 진정한 근대 인테리어예요.","어떤 장식들에도 의존하지 않고 형태와 구조만을 통해 실용적이고 미학적으로도 성공적인 인테리어예요."]},{"kind":"look","walked":1},{"kind":"bg","src":"배경 지식","lines":["네이브는 교회 가운데 긴 본당, 아일은 그 양옆의 낮은 복도예요.","**배럴 보울트 지붕**도 원래 교회에서 쓰던 형식이에요.","**오토 바그너(Otto Wagner)**는 옛 형식을 철과 유리로 새로 만들었어요."]}],"pass3":[{"kind":"check","q":"**우편저축은행** 메인 뱅킹 룸의 중앙 높은 부분과 양쪽 낮은 부분 구성을 부르는 말은?","choices":["**네이브와 아일**","아트리움","로지아"],"a":0,"why":"완전히 근대적인 방식의 네이브와 아일이라고 해요."},{"kind":"check","q":"**우편저축은행** 인테리어에 대한 설명으로 옳은 것은?","choices":["장식을 많이 써서 화려해요","장식에 의존하지 않고 형태와 구조만으로 성공한 최초의 진정한 근대 인테리어예요","장식이 전혀 없어서 실용성만 남았어요"],"a":1,"why":"실용적이면서 미학적으로도 성공적이라는 점이 핵심이에요."},{"kind":"english","head":"논술 답안: 최초의 진정한 근대 인테리어","en":"빈 우편저축은행의 메인 뱅킹 룸은 층고가 높은 중앙 부분과 더 낮은 측면 공간으로 이루어진 완전히 근대적인 방식의 네이브와 아일이며, 지지 기둥은 리벳의 머리들이 노출된 금속이다.","ko":"어떤 장식에도 의존하지 않고 형태와 구조만을 통해 실용적이고 미학적으로도 성공적인 최초의 진정한 근대 인테리어로 평가된다.","tip":"'네이브와 아일 + 리벳 노출 기둥 + 최초의 진정한 근대 인테리어' 세 개를 꼭 써요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.07,0.88,0.33],"c":[0.016,0.0535,0.968,0.363],"r":3.5556,"img":"img/U3/walk/p031_22_01.jpg","say":"네 항목. 네이브와 아일, 리벳 노출 금속 기둥, 최초의 근대 인테리어."},{"b":[0.03,0.48,0.45,0.46],"c":[0.0075,0.457,0.495,0.506],"r":1.3043,"img":"img/U3/walk/p031_22_02.jpg","say":"측면 공간에서 본 모습. 가운데가 높고 이쪽이 낮아요."},{"b":[0.38,0.49,0.1,0.4],"c":[0.33,0.47,0.2,0.44],"r":0.6061,"img":"img/U3/walk/p031_22_03.jpg","say":"기둥 표면에 리벳 머리가 세로로 줄지어 박혀 있어요."},{"b":[0.51,0.48,0.47,0.46],"c":[0.483,0.457,0.517,0.506],"r":1.3623,"img":"img/U3/walk/p031_22_04.jpg","say":"메인 뱅킹 룸 전경. 위를 덮은 것이 **배럴 보울트 지붕**이에요."},{"b":[0.53,0.75,0.44,0.18],"c":[0.508,0.734,0.484,0.212],"r":3.044,"img":"img/U3/walk/p031_22_05.jpg","say":"바닥은 **구조용 유리 바닥**이라 빛이 지하로 내려가요."}]}},{"p":32,"title":"우편저축은행의 구조용 유리 바닥 (캡션 없는 쪽)","terms":["우편저축은행","구조용 유리 바닥"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. 글자 캡션은 없어요.","**우편저축은행** 업무실의 바닥을 가까이서 찍었어요.","네모난 유리 블록이 끝없이 깔려 있어요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["바닥 전체가 네모난 유리 블록으로 되어 있어요. 이것이 **구조용 유리 바닥**이에요.","유리 블록이 빛을 받아 회색으로 반짝여요. 그 빛이 지하로 내려가요.","유리 블록 사이사이에 검은색과 흰색 띠가 십자로 지나가요.","그 띠가 **우편저축은행**에 남은 거의 유일한 장식 무늬예요.","뒤쪽 벽에는 창구 번호판과 시계만 붙어 있고 무늬가 없어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.05,0.45,0.88,0.5],"c":[0.006,0.425,0.968,0.55],"r":2.3467,"img":"img/U3/walk/p032_21_01.jpg","say":"바닥. 네모난 유리 블록이 끝없이 깔려 있어요."},{"b":[0.3,0.55,0.4,0.25],"c":[0.28,0.534,0.44,0.282],"r":2.0804,"img":"img/U3/walk/p032_21_02.jpg","say":"검은색과 흰색 띠가 십자로 지나가요. 남은 장식이 이것뿐이에요."},{"b":[0.05,0.05,0.88,0.28],"c":[0.006,0.034,0.968,0.312],"r":4.1368,"img":"img/U3/walk/p032_21_03.jpg","say":"뒤쪽 창구들. 벽에 무늬가 하나도 없어요."},{"b":[0.11,0.03,0.09,0.09],"c":[0.055,0.014,0.2,0.122],"r":2.1858,"img":"img/U3/walk/p032_21_04.jpg","say":"벽에 걸린 시계예요."},{"b":[0.6,0.1,0.06,0.25],"c":[0.53,0.084,0.2,0.282],"r":0.9456,"img":"img/U3/walk/p032_21_05.jpg","say":"금속 기둥. 표면에 볼트 머리가 박혀 있어요."}]}},{"p":33,"title":"우편저축은행의 입구와 금속 디테일 (캡션 없는 쪽, 문에 PSK 표시)","terms":["우편저축은행","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. 캡션 글은 없어요.","출입문에 PSK 라는 글자가 붙어 있어요. **우편저축은행**의 약자예요.","알루미늄 기둥과 유리 지붕, 대리석 난간이 보여요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 입구 위를 덮은 유리 차양이에요. 가는 금속 살이 유리판을 받치고 있어요.","오른쪽 위: 정면 출입문이에요. 문 위에 숫자 2, 문짝에 PSK 라고 붙어 있어요.","문 양쪽에 알루미늄 기둥이 서 있고 표면에 가로 줄무늬가 있어요.","왼쪽 아래: 대리석 난간이에요. 가는 금속 막대를 세로로 세우고 손잡이를 얹었어요.","오른쪽 아래: 금속 테두리의 유리 부스예요. 나무가 아니라 금속으로 짰어요.","네 장 모두 금속, 유리, 대리석 세 가지 재료만 써요."]},{"kind":"points","head":"무엇을 봐야 할까요","items":["꽃무늬나 조각 장식이 하나도 없어요.","재료를 그대로 드러내고 이음매를 숨기지 않는 것이 **오토 바그너(Otto Wagner)**의 방식이에요.","주문을 떠올려요. 싫어 → 새 장식 → 정리 → 없애. **우편저축은행**은 '없애'에 거의 다 왔어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.02,0.11,0.44,0.45],"c":[0,0.0875,0.484,0.495],"r":1.3037,"img":"img/U3/walk/p033_22_01.jpg","say":"입구 위 유리 차양. 가는 금속 살이 유리판을 받쳐요."},{"b":[0.5,0.1,0.48,0.48],"c":[0.472,0.076,0.528,0.528],"r":1.3333,"img":"img/U3/walk/p033_22_02.jpg","say":"정면 출입문. 문짝에 PSK 라는 글자가 붙어 있어요."},{"b":[0.53,0.16,0.14,0.32],"c":[0.5,0.144,0.2,0.352],"r":0.7576,"img":"img/U3/walk/p033_22_03.jpg","say":"알루미늄 기둥. 표면에 가로 줄무늬가 있어요."},{"b":[0.02,0.6,0.44,0.36],"c":[0,0.582,0.484,0.396],"r":1.6296,"img":"img/U3/walk/p033_22_04.jpg","say":"대리석 난간과 가는 금속 막대예요."},{"b":[0.52,0.59,0.46,0.37],"c":[0.494,0.5715,0.506,0.407],"r":1.6577,"img":"img/U3/walk/p033_22_05.jpg","say":"금속 테두리로 짠 유리 부스예요."}]}},{"p":34,"title":"바그너의 명언: 실용적이지 않은 것은 아름다울 수 없다","terms":["Otto Wagner","우편저축은행"],"pass1":[{"kind":"say","lines":["이 쪽에는 문장 한 줄만 크게 적혀 있어요.","'실용적이지 않은 것은 아름다울 수 없다.'","**오토 바그너(Otto Wagner)**를 한 문장으로 요약한 말이에요."]},{"kind":"recap","items":["바그너를 세 문장으로 정리해요.","'필요만이 예술의 주인'이다.","'실용적이지 않은 것은 아름다울 수 없다.'","그 증거가 **우편저축은행**(1906)의 인테리어예요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽: 업무실 한쪽이에요. 흰 기둥에 검은 세로 줄무늬가 그려져 있어요.","그 줄무늬가 **우편저축은행**에 남은 무늬 장식이에요. 파낸 조각이 아니라 그린 선이에요.","오른쪽 위: 알루미늄 기둥의 머리 부분이에요. 둥근 볼트 머리가 촘촘히 박혀 있어요.","기둥과 천장이 만나는 자리를 숨기지 않고 그대로 보여 줘요.","오른쪽 아래: 이 건물에 쓰인 탁자와 의자예요. 거울판 상판과 굽은 나무 의자예요.","가구까지 **오토 바그너(Otto Wagner)**의 계획 안에 들어와 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'실용적이지 않은 것은 아름다울 수 없다'고 말한 인물은?","choices":["요제프 호프만","**오토 바그너(Otto Wagner)**","아돌프 로스"],"a":1,"why":"바그너예요. '필요만이 예술의 주인'과 짝으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.08,0.43,0.06],"c":[0.0285,0.055,0.473,0.11],"r":5.7333,"img":"img/U3/walk/p034_21_01.jpg","say":"명언. 실용적이지 않은 것은 아름다울 수 없다."},{"b":[0.06,0.22,0.42,0.75],"c":[0.039,0.175,0.462,0.825],"r":0.7467,"img":"img/U3/walk/p034_21_02.jpg","say":"업무실 한쪽. 기둥의 검은 세로 줄무늬가 보여요."},{"b":[0.25,0.35,0.18,0.25],"c":[0.238,0.334,0.204,0.282],"r":0.9645,"img":"img/U3/walk/p034_21_03.jpg","say":"줄무늬 확대. 파낸 조각이 아니라 그린 선이에요."},{"b":[0.52,0.04,0.46,0.46],"c":[0.494,0.017,0.506,0.506],"r":1.3333,"img":"img/U3/walk/p034_21_04.jpg","say":"알루미늄 기둥 머리. 둥근 볼트 머리가 촘촘히 박혀 있어요."},{"b":[0.52,0.53,0.46,0.45],"c":[0.494,0.505,0.506,0.495],"r":1.363,"img":"img/U3/walk/p034_21_05.jpg","say":"탁자와 의자. 가구까지 같은 계획 안에 있어요."}]}},{"p":35,"title":"우편저축은행 홀의 투시도 (캡션 없는 쪽)","terms":["우편저축은행","네이브와 아일","Otto Wagner"],"pass1":[{"kind":"say","lines":["그림 한 장이에요. 캡션 글은 없어요.","정리노트는 이 그림을 '**우편저축은행** 홀의 투시도'로 소개해요.","여러 층이 뚫린 홀을 사람 눈높이에서 그린 그림이에요."]}],"pass2":[{"kind":"points","head":"이 그림에서 볼 것","items":["가운데가 위로 뻥 뚫려 있고 층마다 난간이 둘러싸고 있어요.","기둥은 네모나고 가늘며, 층마다 같은 높이로 반복돼요.","오른쪽 위에 TELEPHONE 이라고 쓴 부스가 보여요.","가운데 아래에는 조각상과 계단이 있고 사람들이 서 있어요.","가운데가 높고 양옆이 낮은 **네이브와 아일**의 느낌을 그림으로도 알 수 있어요.","**오토 바그너(Otto Wagner)**는 이런 그림으로 공간을 미리 보여 줬어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.23,0.02,0.54,0.44],"c":[0.203,0,0.594,0.484],"r":1.6364,"img":"img/U3/walk/p035_21_01.jpg","say":"위층 난간들. 층마다 같은 높이로 반복돼요."},{"b":[0.23,0.5,0.54,0.47],"c":[0.203,0.4765,0.594,0.517],"r":1.5319,"img":"img/U3/walk/p035_21_02.jpg","say":"1층 홀. 계단과 조각상, 사람들이 보여요."},{"b":[0.65,0.61,0.11,0.05],"c":[0.605,0.58,0.2,0.11],"r":2.4242,"img":"img/U3/walk/p035_21_03.jpg","say":"TELEPHONE 이라고 쓴 부스예요."},{"b":[0.23,0.55,0.15,0.4],"c":[0.205,0.53,0.2,0.44],"r":0.6061,"img":"img/U3/walk/p035_21_04.jpg","say":"왼쪽 아래 조각상과 그 받침이에요."}]}},{"p":36,"title":"오토 바그너, 노이슈티프트가세 공동주택, 오스트리아 빈, 1911","terms":["노이슈티프트가세 공동주택","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진과 그림이 함께 있어요. **노이슈티프트가세 공동주택**이에요.","**오토 바그너(Otto Wagner)**가 1911년 오스트리아 빈에 지었어요.","3강에 나오는 바그너 작품 중 가장 늦은 것이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["설계자 **오토 바그너(Otto Wagner)**, 연도 1911년, 장소 오스트리아 빈이에요.","왼쪽 사진은 벽에 붙은 명판이에요. OTTO WAGNER 1912-1918 이라고 적혀 있어요.","바그너가 이 집에서 살다 세상을 떠났다는 뜻의 독일어가 적혀 있어요.","명판 둘레의 벽은 가로 줄무늬가 새겨진 판이에요.","오른쪽은 건물 투시도예요. 벽 위쪽에 NEUSTIFTGASSE 40 이라고 크게 써 넣었어요.","건물 이름이 곧 거리 이름과 번지예요."]},{"kind":"look","walked":1},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["명판의 1912-1918은 건물의 준공 연도가 아니에요. 바그너가 이 집에 산 기간이에요.","**노이슈티프트가세 공동주택**의 연도는 1911년이에요."]}],"pass3":[{"kind":"check","q":"**노이슈티프트가세 공동주택**은 몇 년 작품일까요?","choices":["1901","1906","1911"],"a":2,"why":"1911년, 오스트리아 빈이에요. 바그너 작품 순서의 마지막이에요."},{"kind":"english","head":"논술 답안: 오토 바그너의 주요 작품 순서","en":"오토 바그너의 주요 작품은 앙커하우스(1895), 마욜리카하우스와 링케 빈 차일레 주거블록(1898), 칼스플라츠 역사(1901), 우편저축은행(1906), 노이슈티프트가세 공동주택(1911)이다.","ko":"연도와 작품을 짝지어 쓰는 문제가 자주 나와요.","tip":"'앙-마링-칼-우-노'로 첫 글자만 모아 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.26,0.05],"c":[0.037,0.03,0.286,0.11],"r":3.4667,"img":"img/U3/walk/p036_21_01.jpg","say":"제목. 노이슈티프트가세 공동주택."},{"b":[0.03,0.24,0.41,0.54],"c":[0.0095,0.213,0.451,0.594],"r":1.0123,"img":"img/U3/walk/p036_21_02.jpg","say":"벽에 붙은 명판 사진이에요."},{"b":[0.19,0.34,0.2,0.25],"c":[0.178,0.324,0.224,0.282],"r":1.0591,"img":"img/U3/walk/p036_21_03.jpg","say":"명판 글씨. OTTO WAGNER 1912-1918 이 보여요."},{"b":[0.59,0.03,0.4,0.95],"c":[0.56,0,0.44,1],"r":0.5867,"img":"img/U3/walk/p036_21_04.jpg","say":"건물 투시도. 창이 규칙적으로 뚫린 네모 덩어리예요."},{"b":[0.68,0.15,0.13,0.08],"c":[0.645,0.134,0.2,0.112],"r":2.381,"img":"img/U3/walk/p036_21_05.jpg","say":"벽에 쓴 NEUSTIFTGASSE 40 이라는 글씨예요."},{"b":[0.04,0.93,0.48,0.04],"c":[0.016,0.89,0.528,0.11],"r":6.4,"img":"img/U3/walk/p036_21_06.jpg","say":"캡션. 오토 바그너, 노이슈티프트가세 공동주택, 빈, 1911."}]}},{"p":37,"title":"노이슈티프트가세 공동주택의 실제 모습, 오스트리아 빈, 1911","terms":["노이슈티프트가세 공동주택","Otto Wagner"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. 모두 **노이슈티프트가세 공동주택**이에요.","**오토 바그너(Otto Wagner)**, 오스트리아 빈, 1911년이에요.","앞 쪽 투시도와 같은 글씨가 벽에 그대로 남아 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽: 길모퉁이에서 본 전체예요. 벽이 연한 회색 판으로 덮여 있어요.","벽 위쪽에 NEUSTIFTGASSE 40 이라는 글씨가 그대로 있어요.","창은 크기와 간격이 모두 같고 창틀 장식이 없어요.","저층부에만 가로 줄무늬 띠가 둘러져 있어요.","오른쪽 위: 벽면 확대예요. 층과 층 사이에 짙은 띠가 하나 지나가요.","오른쪽 아래: 저층부 확대예요. 줄무늬 판과 검은 띠가 가로로 이어져요."]},{"kind":"points","head":"바그너의 마지막 단계","items":["1898년 마욜리카하우스의 꽃무늬가 여기서는 완전히 사라졌어요.","남은 것은 판의 줄무늬와 가로 띠, 그리고 벽에 쓴 글씨뿐이에요.","**오토 바그너(Otto Wagner)**가 점점 장식을 줄여 간 흐름을 이 쪽에서 확인해요.","주문을 다시 외워요. 싫어 → 새 장식 → 정리 → 없애."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.04,0.51,0.9],"c":[0.0045,0,0.561,0.99],"r":0.7556,"img":"img/U3/walk/p037_22_01.jpg","say":"길모퉁이에서 본 전체. 연한 회색 판 벽이에요."},{"b":[0.14,0.14,0.12,0.09],"c":[0.1,0.124,0.2,0.122],"r":2.1858,"img":"img/U3/walk/p037_22_02.jpg","say":"벽에 쓴 NEUSTIFTGASSE 40 글씨예요."},{"b":[0.05,0.58,0.45,0.2],"c":[0.0275,0.564,0.495,0.232],"r":2.8448,"img":"img/U3/walk/p037_22_03.jpg","say":"저층부의 가로 줄무늬 띠예요."},{"b":[0.55,0.05,0.44,0.43],"c":[0.516,0.0285,0.484,0.473],"r":1.3643,"img":"img/U3/walk/p037_22_04.jpg","say":"벽면 확대. 층 사이에 짙은 띠가 하나 지나가요."},{"b":[0.55,0.51,0.44,0.43],"c":[0.516,0.4885,0.484,0.473],"r":1.3643,"img":"img/U3/walk/p037_22_05.jpg","say":"저층부 확대. 줄무늬 판과 검은 띠가 이어져요."},{"b":[0.17,0.95,0.5,0.04],"c":[0.145,0.8889,0.55,0.1111],"r":6.6007,"img":"img/U3/walk/p037_22_06.jpg","say":"캡션. 오토 바그너, 노이슈티프트가세 공동주택, 빈, 1911."}]}},{"p":38,"title":"아돌프 로스(Adolf Loos, 1870-1933)와 장식과 죄악","terms":["Adolf Loos","Ornament und Verbrechen","요제프 호프만","Wiener Secession"],"pass1":[{"kind":"say","lines":["3강의 마지막 주인공 **아돌프 로스(Adolf Loos)**예요. 1870-1933년 사람이에요.","1908년 논문 **장식과 죄악(Ornament und Verbrechen)**에서 장식을 비난했어요.","'장식은 죄악' 아저씨로 기억하면 돼요."]},{"kind":"analogy","head":"로스는 장식을 치우는 아저씨","scene":"책상에 붙인 스티커를 전부 떼면서 '쓸모없다'고 잔소리하는 아저씨 같아요.","map":[["떼어 낸 스티커","아무 쓸모 없는 타락의 표현인 장식"],["왜 떼나요","기계로 만드는 시대에 맞지 않아서예요"],["누구와 싸우나요","**요제프 호프만**과 **빈 분리파(Wiener Secession)**의 예쁜 취향"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**아돌프 로스(Adolf Loos)**: 1870-1933. 장식을 타락이라 비난한 빈의 건축가예요.","**장식과 죄악(Ornament und Verbrechen)**: 1908년에 쓴 논문의 제목이에요.","독일어 제목이 시험에 그대로 나와요. Ornament 는 장식, Verbrechen 은 죄악이에요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["1908년 논문 **장식과 죄악(Ornament und Verbrechen)**에서 장식의 사용을 비난했어요.","장식은 아무런 쓸모가 없는 타락의 표현이며 근대문명에서 제거되는 것이 최상이라고 주장했어요.","장식을 근대의 기계화된 생산방법에 적합하지 않은 것으로 본 그의 견해는 많은 20세기 디자인의 중심을 이뤘어요.","**요제프 호프만**과 대척점에 서서 제체시온의 심미적 경향을 강하게 비판했어요."]},{"kind":"compare","head":"호프만과 로스는 정반대예요","cols":["항목","**요제프 호프만**","**아돌프 로스(Adolf Loos)**"],"rows":[["생몰년","1870-1956","1870-1933"],["장식","총체예술로 끝까지 디자인해요","타락이니 제거하라고 해요"],["기계 생산","반대하고 장인 기술을 써요","장식이 기계 생산에 안 맞는다고 해요"],["제체시온","그 흐름의 중심이에요","심미적 경향을 강하게 비판해요"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아돌프 로스(Adolf Loos)**의 생몰년은?","choices":["1841-1918","1870-1933","1870-1956"],"a":1,"why":"1870-1933이에요. 호프만과 태어난 해는 같지만 세상을 떠난 해가 달라요."},{"kind":"check","q":"로스가 대척점에 서서 비판한 인물과 경향은?","choices":["오토 바그너와 기능주의","**요제프 호프만**과 제체시온의 심미적 경향","올브리히와 유겐트슈틸"],"a":1,"why":"호프만과 **빈 분리파(Wiener Secession)**의 예쁜 취향을 강하게 비판했어요."},{"kind":"english","head":"논술 답안: 장식과 죄악","en":"아돌프 로스는 1908년 논문 Ornament und Verbrechen(장식과 죄악)에서 장식의 사용을 비난하며, 장식은 아무런 쓸모가 없는 타락의 표현이고 근대문명에서 제거되는 것이 최상이라고 주장하였다.","ko":"장식을 근대의 기계화된 생산방법에 적합하지 않은 것으로 본 그의 견해는 많은 20세기 디자인의 중심을 이루었으며, 호프만과 대척점에서 제체시온의 심미적 경향을 강하게 비판하였다.","tip":"'1908 + 독일어 제목 + 타락 + 기계 생산 + 호프만 대척' 다섯 개예요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.07,0.36,0.05],"c":[0.042,0.04,0.396,0.11],"r":4.8,"img":"img/U3/walk/p038_23_01.jpg","say":"이름과 생몰년. 아돌프 로스, 1870-1933."},{"b":[0.04,0.14,0.9,0.2],"c":[0,0.124,0.99,0.232],"r":5.6897,"img":"img/U3/walk/p038_23_02.jpg","say":"앞 세 항목. 1908년 논문, 장식은 타락, 기계 생산에 부적합."},{"b":[0.04,0.37,0.55,0.12],"c":[0.0125,0.354,0.605,0.152],"r":5.307,"img":"img/U3/walk/p038_23_03.jpg","say":"넷째 항목. 호프만과 대척, 제체시온의 심미적 경향 비판."},{"b":[0.27,0.52,0.2,0.44],"c":[0.258,0.498,0.224,0.484],"r":0.6171,"img":"img/U3/walk/p038_23_04.jpg","say":"로스의 초상 사진이에요."},{"b":[0.54,0.35,0.4,0.62],"c":[0.52,0.318,0.44,0.682],"r":0.8602,"img":"img/U3/walk/p038_23_05.jpg","say":"ADOLF LOOS 라고 적힌 책 표지예요. 대리석 기둥과 격자 유리문이 보여요."}]}},{"p":39,"title":"아돌프 로스, 아메리칸 바, 오스트리아 빈, 1908","terms":["아메리칸 바","Adolf Loos"],"pass1":[{"kind":"say","lines":["**아메리칸 바**는 **아돌프 로스(Adolf Loos)**의 1908년 작품이에요.","오스트리아 빈에 있는 아주 작은 바예요.","거울로 공간을 무한히 넓어 보이게 만든 것이 핵심이에요."]},{"kind":"analogy","head":"거울로 늘린 방","scene":"엘리베이터 안의 거울 때문에 방이 두 배로 보이는 것과 같아요.","map":[["작은 실제 방","**아메리칸 바**의 좁은 실내"],["벽에 세운 수직 거울","대리석 천장을 그대로 비춰요"],["눈에 보이는 결과","시각적으로 공간이 무제한 확장돼요"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["입구의 돌출된 프리즘 형태의 색유리 현관이 특징이에요.","4개의 대리석 벽기둥과 황동 유리 현관이 있어요.","실내의 수직 거울이 대리석 천장을 반사하여 시각적으로 공간을 무제한 확장해요.","프리즘은 삼각기둥처럼 각진 덩어리를 말해요. 현관이 벽에서 툭 튀어나와 있어요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["오른쪽 위: 입구예요. American Bar 라는 글씨와 미국 국기 무늬가 색유리로 붙어 있어요.","그 아래 양쪽에 붉은 무늬의 대리석 기둥이 서 있어요.","왼쪽 아래: 바 안쪽이에요. 어두운 나무와 천장의 네모 격자가 보여요.","가운데 아래: 앉는 자리예요. 위쪽 띠가 반짝이는 것이 **아메리칸 바**의 거울이에요.","천장의 무늬가 거울에 비쳐서 방이 계속 이어지는 것처럼 보여요."]},{"kind":"look","walked":1},{"kind":"bg","src":"배경 지식","lines":["**아메리칸 바**는 크라이너 바라고도 불려요.","강의자료에는 연도(1908)와 위치(빈)만 나오니 그 두 가지만 외우면 돼요."]}],"pass3":[{"kind":"check","q":"**아메리칸 바** 실내를 시각적으로 무제한 확장시키는 요소는?","choices":["수직 거울","유리 천장","흰색 페인트"],"a":0,"why":"수직 거울이 대리석 천장을 반사해서 공간이 끝없이 이어져 보여요."},{"kind":"check","q":"**아메리칸 바** 입구의 특징은?","choices":["돌출된 프리즘 형태의 색유리 현관","둥근 아치 현관","벽돌로 쌓은 현관"],"a":0,"why":"돌출된 프리즘 형태의 색유리 현관과 4개의 대리석 벽기둥이에요."},{"kind":"english","head":"논술 답안: 아메리칸 바","en":"아메리칸 바는 아돌프 로스가 1908년 빈에 설계한 바로, 입구의 돌출된 프리즘 형태의 색유리 현관과 4개의 대리석 벽기둥, 황동 유리 현관이 특징이다.","ko":"실내의 수직 거울이 대리석 천장을 반사하여 시각적으로 공간을 무제한 확장한다.","tip":"'프리즘 색유리 현관 + 대리석 기둥 4개 + 수직 거울' 세 개예요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.07,0.16,0.05],"c":[0.02,0.04,0.2,0.11],"r":2.4242,"img":"img/U3/walk/p039_22_01.jpg","say":"제목. 아메리칸 바."},{"b":[0.04,0.13,0.46,0.27],"c":[0.017,0.114,0.506,0.302],"r":2.234,"img":"img/U3/walk/p039_22_02.jpg","say":"세 항목. 프리즘 색유리 현관, 대리석 기둥 4개, 수직 거울."},{"b":[0.51,0.02,0.48,0.52],"c":[0.472,0,0.528,0.572],"r":1.2308,"img":"img/U3/walk/p039_22_03.jpg","say":"입구. 색유리로 만든 American Bar 간판과 국기 무늬예요."},{"b":[0.57,0.26,0.28,0.26],"c":[0.556,0.244,0.308,0.292],"r":1.4064,"img":"img/U3/walk/p039_22_04.jpg","say":"붉은 무늬의 대리석 기둥과 황동 유리문이에요."},{"b":[0.02,0.48,0.26,0.47],"c":[0.007,0.4565,0.286,0.517],"r":0.7376,"img":"img/U3/walk/p039_22_05.jpg","say":"바 안쪽. 어두운 나무와 네모 격자 천장이에요."},{"b":[0.29,0.48,0.62,0.51],"c":[0.259,0.439,0.682,0.561],"r":1.6209,"img":"img/U3/walk/p039_22_06.jpg","say":"앉는 자리 위쪽의 반짝이는 띠가 거울이에요. 캡션은 아돌프 로스, 아메리칸 바, 오스트리아 빈, 1908 이에요."}]}},{"p":40,"title":"아돌프 로스, 골트만 운트 잘라치 빌딩(로스하우스), 오스트리아 빈, 1912","terms":["로스하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["**로스하우스**는 **아돌프 로스(Adolf Loos)**의 1912년 빈 작품이에요.","원래 이름은 골트만 운트 잘라치 빌딩이에요.","장식이 없어서 '곡물창고'라고 놀림받으며 논란이 됐어요."]},{"kind":"analogy","head":"창문만 뚫린 상자","scene":"무늬 없는 종이 상자에 네모 구멍만 뚫어 놓은 것 같아요.","map":[["아래층 상가","녹색 대리석으로 마감"],["위층 주거","매끄러운 회반죽으로 마감"],["동네 사람들의 반응","'곡물창고'라고 비유하며 논란"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["하부 상업 공간은 녹색 대리석 마감이에요.","상부 주거 부분은 매끄러운 회반죽으로 마감했어요.","매끈하고 품격 있는 표면에 대한 열정 때문이에요.","장식이 없는 외관 때문에 '곡물창고'에 비유되며 논란이 됐어요.","회반죽은 벽에 바르는 석회 반죽이에요. 마르면 매끈한 흰 면이 돼요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽은 옛날 사진이에요. 왼쪽에 곡선 장식이 잔뜩 붙은 옛 건물이 보여요.","그 옆에 창만 뚫린 **로스하우스**가 나란히 서 있어요. 대비가 한눈에 보여요.","오른쪽은 지금 사진이에요. 위쪽 벽에 창만 규칙적으로 뚫려 있어요.","아래층은 색이 진하고 무늬가 있는 대리석이에요.","위층과 아래층의 재료가 확 달라서 두 덩어리로 나뉘어 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**로스하우스** 하부 상업 공간의 마감은?","choices":["녹색 대리석","매끄러운 회반죽","붉은 벽돌"],"a":0,"why":"하부는 녹색 대리석, 상부 주거는 매끄러운 회반죽이에요."},{"kind":"check","q":"**로스하우스**가 무장식 외관 때문에 비유된 말은?","choices":["유리 궁전","곡물창고","성냥갑"],"a":1,"why":"'곡물창고'에 비유되며 논란이 됐어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["상부 주거가 녹색 대리석이라고 하면 틀려요. 녹색 대리석은 하부 상업 공간이에요.","**로스하우스**의 원래 이름은 골트만 운트 잘라치 빌딩이에요."]},{"kind":"english","head":"논술 답안: 로스하우스","en":"로스하우스는 아돌프 로스가 1912년 빈에 설계한 골트만 운트 잘라치 빌딩으로, 하부 상업 공간은 녹색 대리석으로, 상부 주거 부분은 매끄러운 회반죽으로 마감하였다.","ko":"매끈하고 품격 있는 표면에 대한 열정을 보여 주지만 장식이 없는 외관 때문에 곡물창고에 비유되며 논란이 되었다.","tip":"'1912 + 빈 + 녹색 대리석 + 회반죽 + 곡물창고'로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.07,0.3,0.05],"c":[0.055,0.04,0.33,0.11],"r":4.0,"img":"img/U3/walk/p040_22_01.jpg","say":"제목. 로스하우스(골드만 운트 잘라치)."},{"b":[0.06,0.12,0.88,0.18],"c":[0.016,0.104,0.968,0.212],"r":6.0881,"img":"img/U3/walk/p040_22_02.jpg","say":"두 항목. 하부 녹색 대리석, 상부 회반죽, 곡물창고 비유."},{"b":[0.01,0.4,0.53,0.45],"c":[0,0.3775,0.583,0.495],"r":1.5704,"img":"img/U3/walk/p040_22_03.jpg","say":"옛날 사진. 왼쪽 옛 건물과 오른쪽 로스하우스가 나란해요."},{"b":[0.3,0.5,0.22,0.3],"c":[0.288,0.484,0.244,0.332],"r":0.9799,"img":"img/U3/walk/p040_22_04.jpg","say":"창만 뚫린 로스하우스. 장식이 하나도 없어요."},{"b":[0.55,0.4,0.42,0.43],"c":[0.529,0.3785,0.462,0.473],"r":1.3023,"img":"img/U3/walk/p040_22_05.jpg","say":"지금 사진. 위층은 흰 회반죽, 아래층은 녹색 대리석이에요."},{"b":[0.54,0.87,0.42,0.08],"c":[0.519,0.854,0.462,0.112],"r":5.5,"img":"img/U3/walk/p040_22_06.jpg","say":"캡션. 아돌프 로스, 골트만 운트 잘라치 빌딩, 빈, 1912."}]}},{"p":41,"title":"로스하우스의 대리석 기둥과 저층부 (캡션 없는 쪽)","terms":["로스하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. 캡션 글은 없어요.","앞 쪽과 같은 건물, 즉 **로스하우스**의 저층부예요.","녹색 무늬 대리석 기둥이 아주 가까이 보여요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 저층부 정면이에요. 굵은 원기둥 네 개가 서 있고 그 사이가 유리창이에요.","기둥과 벽 모두 초록빛 무늬가 흐르는 대리석이에요.","왼쪽 아래: 현관 위를 올려다본 사진이에요. 대리석 기둥 두 개와 격자 유리가 보여요.","지금은 그 자리에 은행 간판이 걸려 있어요.","오른쪽: 길 건너에서 본 전체예요. 위층은 흰 벽에 창만 뚫려 있어요.","아래층의 화려한 대리석과 위층의 민민한 흰 벽이 확실히 대비돼요."]},{"kind":"points","head":"무엇이 시험 포인트일까요","items":["**로스하우스**는 아래는 화려한 재료, 위는 아무 장식 없는 면이에요.","장식을 새기는 대신 재료 자체의 무늬를 보여 줘요.","**아돌프 로스(Adolf Loos)**가 말한 '매끈하고 품격 있는 표면'이 이 방식이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.04,0.03,0.4,0.44],"c":[0.02,0.008,0.44,0.484],"r":1.2121,"img":"img/U3/walk/p041_22_01.jpg","say":"저층부 정면. 굵은 대리석 원기둥 네 개가 서 있어요."},{"b":[0.12,0.13,0.2,0.2],"c":[0.108,0.114,0.224,0.232],"r":1.2874,"img":"img/U3/walk/p041_22_02.jpg","say":"기둥과 벽의 초록빛 대리석 무늬예요."},{"b":[0.04,0.5,0.42,0.45],"c":[0.019,0.4775,0.462,0.495],"r":1.2444,"img":"img/U3/walk/p041_22_03.jpg","say":"현관을 올려다본 사진. 대리석 기둥과 격자 유리예요."},{"b":[0.48,0.24,0.5,0.52],"c":[0.45,0.214,0.55,0.572],"r":1.2821,"img":"img/U3/walk/p041_22_04.jpg","say":"길 건너에서 본 전체. 위층은 흰 벽에 창만 뚫려 있어요."},{"b":[0.62,0.28,0.25,0.2],"c":[0.6075,0.264,0.275,0.232],"r":1.5805,"img":"img/U3/walk/p041_22_05.jpg","say":"위층의 민민한 흰 벽. 장식이 하나도 없어요."}]}},{"p":42,"title":"로스하우스의 실내, 오스트리아 빈, 1912 (1996 촬영)","terms":["로스하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. **로스하우스**의 실내예요.","캡션에 1912년 작품이고 1996년에 찍은 사진이라고 적혀 있어요.","겉은 장식이 없었는데 안은 나무와 대리석으로 꽉 차 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽: 벽과 천장이 짙은 나무로 덮인 방이에요. 천장에 나무 보가 격자로 드러나 있어요.","가죽 소파와 카펫, 벽난로 위 초상화가 보여요. 아주 아늑한 방이에요.","창은 작은 유리 블록으로 되어 있어서 빛만 들어와요.","오른쪽: 계단 옆의 거울 벽이에요. 짙은 나무와 유리가 서로를 비춰요.","천장에는 무늬가 새겨진 밝은 판이 깔려 있어요.","겉은 무장식, 속은 값비싼 재료. 이것이 **아돌프 로스(Adolf Loos)** 건물의 특징이에요."]},{"kind":"look","walked":1},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["캡션의 1996은 사진을 찍은 해예요. 건물 연도는 1912년이에요.","**로스하우스**는 겉은 무장식이지만 내부는 장식에서 완전히 벗어나지 못했어요."]}],"pass3":[{"kind":"check","q":"로스 건물의 겉과 속에 대한 설명으로 옳은 것은?","choices":["겉도 속도 완전히 무장식이에요","겉은 무장식이지만 내부는 장식에서 완전히 벗어나지 못했어요","겉은 화려하고 속은 텅 비었어요"],"a":1,"why":"무장식 외관과 값비싼 재료의 내부가 로스의 특징이에요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.1,0.44,0.68],"c":[0.018,0.066,0.484,0.748],"r":0.8627,"img":"img/U3/walk/p042_21_01.jpg","say":"나무로 덮인 방. 천장에 나무 보가 격자로 드러나 있어요."},{"b":[0.05,0.28,0.14,0.4],"c":[0.02,0.26,0.2,0.44],"r":0.6061,"img":"img/U3/walk/p042_21_02.jpg","say":"창. 작은 유리 블록으로 되어 있어요."},{"b":[0.53,0.1,0.42,0.68],"c":[0.509,0.066,0.462,0.748],"r":0.8235,"img":"img/U3/walk/p042_21_03.jpg","say":"계단 옆 거울 벽. 나무와 유리가 서로를 비춰요."},{"b":[0.55,0.12,0.38,0.18],"c":[0.531,0.104,0.418,0.212],"r":2.6289,"img":"img/U3/walk/p042_21_04.jpg","say":"천장의 무늬 판. 안쪽에는 장식이 남아 있어요."},{"b":[0.5,0.81,0.42,0.09],"c":[0.479,0.794,0.462,0.122],"r":5.0492,"img":"img/U3/walk/p042_21_05.jpg","say":"캡션. 아돌프 로스, 로스 하우스, 빈, 1912, 1996 촬영."}]}},{"p":43,"title":"아돌프 로스, 카페 무제움, 오스트리아 빈","terms":["카페 무제움","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. **카페 무제움**이에요.","**아돌프 로스(Adolf Loos)**의 빈 초기작 카페예요.","지금 실내는 Josef Jotti 의 디자인이라고 캡션에 적혀 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 건물 바깥벽이에요. CAFE MUSEUM 이라고 금색 글씨가 크게 붙어 있어요.","그 아래 창마다 사람 얼굴 사진이 액자처럼 걸려 있어요.","오른쪽 위: 길모퉁이에서 본 전체예요. 노란 벽에 창이 규칙적으로 뚫려 있어요.","아래 두 장: 지금의 실내예요. 붉은 소파와 둥근 탁자, 흰 아치 천장이 보여요.","천장에 매달린 은색 공 모양 조명이 눈에 띄어요.","다만 지금 실내는 로스의 원래 디자인이 아니라고 캡션이 알려 줘요."]},{"kind":"look","walked":1},{"kind":"warn","head":"강의자료의 연도 표기에 주의해요","items":["슬라이드 캡션에는 **카페 무제움**의 연도가 1988로 적혀 있어요.","**아돌프 로스(Adolf Loos)**는 1933년에 세상을 떠났으니 1988년 작품일 수 없어요.","정리노트는 통상 1899년 작으로 알려져 있다고 적어 뒀어요. 시험에서는 1899를 고르면 돼요."]}],"pass3":[{"kind":"check","q":"**카페 무제움**은 통상 몇 년 작으로 알려져 있을까요?","choices":["1899","1912","1988"],"a":0,"why":"강의자료의 1988은 표기 실수로 보여요. 통상 1899년 작이에요."}],"walk":{"head":null,"parts":[{"b":[0.03,0.03,0.56,0.37],"c":[0.002,0.0115,0.616,0.407],"r":2.018,"img":"img/U3/walk/p043_21_01.jpg","say":"바깥벽. CAFE MUSEUM 이라는 금색 글씨가 보여요."},{"b":[0.62,0.03,0.34,0.37],"c":[0.603,0.0115,0.374,0.407],"r":1.2252,"img":"img/U3/walk/p043_21_02.jpg","say":"길모퉁이에서 본 전체. 노란 벽에 창이 규칙적이에요."},{"b":[0.01,0.43,0.51,0.51],"c":[0,0.4045,0.561,0.561],"r":1.3333,"img":"img/U3/walk/p043_21_03.jpg","say":"지금의 실내. 붉은 소파와 둥근 탁자예요."},{"b":[0.52,0.43,0.33,0.51],"c":[0.5035,0.4045,0.363,0.561],"r":0.8627,"img":"img/U3/walk/p043_21_04.jpg","say":"실내 안쪽. 은색 공 모양 조명이 매달려 있어요."},{"b":[0.42,0.95,0.56,0.04],"c":[0.384,0.8755,0.616,0.1245],"r":6.5971,"img":"img/U3/walk/p043_21_05.jpg","say":"캡션. 아돌프 로스, 카페 무제움, 빈, 현재 Josef Jotti 디자인."}]}},{"p":44,"title":"아돌프 로스 디자인의 단독주택들과 라움플란, 슈타이너 하우스 1910","terms":["Raumplan","슈타이너 하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["이 쪽부터 **아돌프 로스(Adolf Loos)**의 단독주택과 **라움플란(Raumplan)** 이야기예요.","첫 작품이 **슈타이너 하우스**, 1910년 오스트리아 빈이에요.","겉은 장식 없는 청교도적 디자인이에요."]},{"kind":"analogy","head":"청교도적 디자인","scene":"꾸밈없이 단정한 교복 같은 집이에요.","map":[["장식 없는 겉모습","우아하고 엄정한 단순한 입체 형상"],["그래도 남는 아름다움","무장식이 비례를 더욱 돋보이게 해요"],["숨은 반전","그러나 내부는 장식에서 완전히 벗어나지 못했어요"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["장식 없는 청교도적 디자인이에요.","우아하고 엄정한 단순한 입체 형상이에요.","그러나 내부는 장식에서 완전히 벗어나지 못했어요.","극적으로 배열된 내부의 볼륨을 보여주는 측면이에요.","건축 공간을 지적이고 기하학적으로 해석했어요.","무장식이 비례를 더욱 돋보이게 해요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["두 장 모두 **슈타이너 하우스**예요. 아돌프 로스, 오스트리아 빈, 1910년이에요.","지붕이 둥근 반원 통처럼 앞으로 휘어 내려와요. 아주 특이한 모양이에요.","벽은 흰색 한 가지이고 무늬가 하나도 없어요.","창은 크기가 제각각이에요. 큰 창, 작은 네모 창이 섞여 있어요.","창 크기가 다른 이유는 안쪽 방마다 필요한 높이와 밝기가 다르기 때문이에요.","이것이 다음 쪽부터 배울 **라움플란(Raumplan)**의 힌트예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"로스 단독주택의 외관 디자인을 표현한 말은?","choices":["장식 없는 청교도적 디자인","화려한 바로크적 디자인","곡선 중심의 아르누보 디자인"],"a":0,"why":"장식 없는 청교도적 디자인, 우아하고 엄정한 단순한 입체 형상이에요."},{"kind":"check","q":"**슈타이너 하우스**는 몇 년, 어디에 지어졌을까요?","choices":["1908년 빈","1910년 빈","1930년 프라하"],"a":1,"why":"1910년 오스트리아 빈이에요. 1930년 프라하는 뮐러 하우스예요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.05,0.55,0.05],"c":[0.0225,0.0139,0.605,0.1222],"r":6.6012,"img":"img/U3/walk/p044_22_01.jpg","say":"제목. 아돌프 로스 디자인의 단독주택들과 라움플란."},{"b":[0.02,0.12,0.47,0.46],"c":[0,0.097,0.517,0.506],"r":1.3623,"img":"img/U3/walk/p044_22_02.jpg","say":"슈타이너 하우스 한쪽. 흰 벽과 둥근 지붕이 보여요."},{"b":[0.51,0.12,0.44,0.46],"c":[0.488,0.097,0.484,0.506],"r":1.2754,"img":"img/U3/walk/p044_22_03.jpg","say":"슈타이너 하우스 정면. 창 크기가 제각각이에요."},{"b":[0.51,0.6,0.4,0.03],"c":[0.49,0.56,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p044_22_04.jpg","say":"캡션. 아돌프 로스, 슈타이너 하우스, 오스트리아 빈, 1910."},{"b":[0.06,0.63,0.51,0.34],"c":[0.0345,0.613,0.561,0.374],"r":2.0,"img":"img/U3/walk/p044_22_05.jpg","say":"여섯 항목. 청교도적 디자인부터 무장식과 비례까지예요."}]}},{"p":45,"title":"아돌프 로스, 슈타이너 하우스, 오스트리아 빈, 1910 (외부와 내부)","terms":["슈타이너 하우스","Adolf Loos","Raumplan"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. 모두 **슈타이너 하우스**예요.","**아돌프 로스(Adolf Loos)**, 오스트리아 빈, 1910년이에요.","왼쪽은 바깥, 오른쪽은 안쪽 흑백 사진이에요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 길 쪽에서 본 모습이에요. 지붕이 반원 통처럼 휘어 내려와요.","왼쪽 아래: 정원 쪽 모습이에요. 이쪽은 평평한 지붕에 네모 상자 모양이에요.","창의 크기와 높이가 층마다 제각각이에요. 안쪽 방의 사정에 맞춘 거예요.","오른쪽 위: 실내예요. 천장에 나무 보가 격자로 드러나 있고 커튼으로 방을 나눴어요.","오른쪽 아래: 다른 방이에요. 벽에 나무판을 두르고 벽돌 벽난로를 놓았어요.","장식 무늬는 없지만 나무와 벽돌의 결이 그대로 보여요."]},{"kind":"points","head":"겉과 속의 차이","items":["겉은 흰 벽에 창만 뚫린 단순한 입체예요.","속은 나무와 벽돌로 아늑하게 꾸며져 있어요. 내부는 장식에서 완전히 벗어나지 못했어요.","방마다 천장 높이가 달라 보이는 점을 눈여겨봐요.","이것이 **라움플란(Raumplan)**으로 이어져요. 다음 파일에서 자세히 배워요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**슈타이너 하우스**의 창 크기가 제각각인 까닭으로 알맞은 설명은?","choices":["재료가 모자라서","안쪽 방마다 필요한 높이와 밝기가 달라서","공사 실수라서"],"a":1,"why":"방의 사정에 맞춰 겉을 정한 것이고, 그 생각이 **라움플란(Raumplan)**으로 이어져요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.1,0.42,0.36],"c":[0.019,0.082,0.462,0.396],"r":1.5556,"img":"img/U3/walk/p045_22_01.jpg","say":"길 쪽 모습. 지붕이 반원 통처럼 휘어 내려와요."},{"b":[0.04,0.49,0.42,0.4],"c":[0.019,0.47,0.462,0.44],"r":1.4,"img":"img/U3/walk/p045_22_02.jpg","say":"정원 쪽 모습. 평평한 지붕의 네모 상자예요."},{"b":[0.07,0.55,0.3,0.2],"c":[0.055,0.534,0.33,0.232],"r":1.8966,"img":"img/U3/walk/p045_22_03.jpg","say":"창의 크기와 높이가 층마다 제각각이에요."},{"b":[0.52,0.02,0.46,0.42],"c":[0.494,0,0.506,0.462],"r":1.4603,"img":"img/U3/walk/p045_22_04.jpg","say":"실내. 나무 보 천장과 커튼으로 나눈 방이에요."},{"b":[0.51,0.49,0.46,0.45],"c":[0.487,0.4675,0.506,0.495],"r":1.363,"img":"img/U3/walk/p045_22_05.jpg","say":"다른 방. 나무판 벽과 벽돌 벽난로예요."},{"b":[0.05,0.94,0.4,0.04],"c":[0.03,0.89,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p045_22_06.jpg","say":"캡션. 아돌프 로스, 슈타이너 하우스, 오스트리아 빈, 1910."}]}},{"p":46,"title":"아돌프 로스, 슈트라서 하우스, 오스트리아 빈, 1918","terms":["슈트라서 하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진과 도면 네 장이에요. **슈트라서 하우스**예요.","**아돌프 로스(Adolf Loos)**가 1918년 오스트리아 빈에 지었어요.","**슈타이너 하우스**(1910) 다음, **뮐러 하우스**(1930) 앞에 오는 집이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["설계자 **아돌프 로스(Adolf Loos)**, 연도 1918년, 장소 오스트리아 빈이에요.","왼쪽 위: 실내예요. 계단이 거실 옆으로 곧장 올라가고 벽에 벽돌이 드러나 있어요.","오른쪽 위: 단면도와 평면도예요. 단면도에서 층마다 바닥 높이가 어긋나 있어요.","왼쪽 아래: 바깥 모습이에요. 흰 벽에 담쟁이가 덮여 있고 지붕 한쪽이 둥글어요.","오른쪽 아래: 식당이에요. 벽 위쪽에 띠 장식이 새겨져 있고 대리석 벽난로가 있어요.","겉은 단순하지만 안은 이렇게 꾸며져 있어요."]},{"kind":"points","head":"단면도를 꼭 봐요","items":["오른쪽 위 단면도에서 검은 가로줄이 바닥이에요.","그 줄들이 층마다 같은 높이로 딱 맞지 않고 조금씩 어긋나 있어요.","방마다 필요한 높이를 따로 준 결과예요.","이것이 **슈트라서 하우스**에서 보이는 로스의 설계 방식이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**슈타이너 하우스**와 **슈트라서 하우스**의 연도는?","choices":["1910년과 1918년","1908년과 1912년","1918년과 1930년"],"a":0,"why":"슈타이너 1910, 슈트라서 1918, 뮐러 1930 순서예요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.04,0.42,0.39],"c":[0,0.0205,0.462,0.429],"r":1.4359,"img":"img/U3/walk/p046_22_01.jpg","say":"실내. 계단이 거실 옆으로 곧장 올라가요."},{"b":[0.45,0.03,0.53,0.4],"c":[0.417,0.01,0.583,0.44],"r":1.7667,"img":"img/U3/walk/p046_22_02.jpg","say":"단면도와 평면도. 층마다 바닥 높이가 어긋나 있어요."},{"b":[0.46,0.08,0.22,0.32],"c":[0.448,0.064,0.244,0.352],"r":0.9242,"img":"img/U3/walk/p046_22_03.jpg","say":"단면도 부분. 검은 가로줄이 각 층 바닥이에요."},{"b":[0.01,0.46,0.43,0.46],"c":[0,0.437,0.473,0.506],"r":1.2464,"img":"img/U3/walk/p046_22_04.jpg","say":"바깥 모습. 흰 벽에 담쟁이가 덮여 있어요."},{"b":[0.46,0.45,0.52,0.47],"c":[0.428,0.4265,0.572,0.517],"r":1.4752,"img":"img/U3/walk/p046_22_05.jpg","say":"식당. 벽 위쪽 띠 장식과 대리석 벽난로예요."},{"b":[0.54,0.95,0.4,0.04],"c":[0.52,0.89,0.44,0.11],"r":5.3333,"img":"img/U3/walk/p046_22_06.jpg","say":"캡션. 아돌프 로스, 슈트라서 하우스, 오스트리아 빈, 1918."}]}},{"p":47,"title":"라움플란(Raumplan): 나는 평면이 아니라 공간을 설계한다","terms":["Raumplan","Adolf Loos","슈트라서 하우스","슈타이너 하우스","Raumkunst","Total Art"],"pass1":[{"kind":"say","lines":["이 쪽이 **라움플란(Raumplan)**의 정의예요.","영어로 옮기면 space plan, 사전적 의미는 공간계획이에요.","하지만 **아돌프 로스(Adolf Loos)**에게는 공간계획 이상의 뜻이 있어요."]},{"kind":"analogy","head":"라움플란은 레고 방 쌓기","scene":"같은 높이로 층을 쌓는 대신 방마다 필요한 높이의 블록을 맞물리게 끼워요.","map":[["같은 높이 층 쌓기","보통 집의 평면 계획"],["방마다 다른 높이 블록","**라움플란(Raumplan)**"],["끼워 맞춘 결과","지상층도 이층도 없고 방과 곁방, 테라스만 있어요"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**라움플란(Raumplan)**: 방마다 필요한 높이를 따로 주고 입체적으로 맞물리게 짜는 설계법이에요.","영어 번역은 space plan 이고 사전적 의미는 공간계획이에요.","**라움쿤스트(Raumkunst)**와 이름이 비슷하지만 다른 말이에요.","**라움쿤스트(Raumkunst)**는 공간 자체가 예술이 되는 수준, 즉 **총체예술(Total Art)**의 목표예요."]},{"kind":"points","head":"로스의 선언 그대로","items":["'나는 평면, 입면, 단면이 아니라 공간을 설계한다.'","'사실상 나의 설계에는 지상층도, 이층도, 지하층도 없다.'","'단지 조합된 방들, 곁방들, 그리고 테라스들만이 있을 뿐이다.'","'모든 방은 각각 특정한 층고를 요구하므로 천장은 각기 상이한 높이들로 배열되어야 한다.'","'이러한 실들은 변화가 지각되지 않고 자연스러우며 기능적으로 구성되어야만 한다.'"]},{"kind":"look","walked":1},{"kind":"compare","head":"이름이 비슷한 세 가지를 구분해요","cols":["용어","누구의 말","뜻"],"rows":[["**총체예술(Total Art)**","**요제프 호프만**","건물부터 가구까지 하나의 앙상블"],["**라움쿤스트(Raumkunst)**","총체예술의 목표","공간 자체가 예술이 되는 수준"],["**라움플란(Raumplan)**","**아돌프 로스(Adolf Loos)**","방마다 높이를 달리해 입체로 짜는 설계법"]]}],"pass3":[{"kind":"check","q":"**라움플란(Raumplan)**의 영어 번역은?","choices":["room plan","space plan","floor plan"],"a":1,"why":"space plan 이고 사전적 의미는 공간계획이에요."},{"kind":"check","q":"**라움플란(Raumplan)**에서 천장 높이에 대한 설명은?","choices":["모든 방의 천장 높이를 같게 해요","모든 방이 특정한 층고를 요구하므로 천장은 각기 상이한 높이로 배열해요","천장을 없애요"],"a":1,"why":"'모든 방은 각각 특정한 층고를 요구한다'가 핵심 문장이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**라움쿤스트(Raumkunst)**는 공간 예술, **라움플란(Raumplan)**은 로스의 설계법이에요.","이름이 비슷해서 바꿔치기한 보기가 자주 나와요."]},{"kind":"english","head":"논술 답안: 라움플란","en":"라움플란은 영어로 space plan 이며 사전적 의미는 공간계획이지만, 로스에게는 그 이상의 의미를 갖는다.","ko":"로스는 나는 평면, 입면, 단면이 아니라 공간을 설계한다고 하였고, 조합된 방들과 곁방들과 테라스들만이 있으며 모든 방이 각각 특정한 층고를 요구하므로 천장은 각기 상이한 높이들로 배열되어야 한다고 하였다.","tip":"'space plan + 공간을 설계한다 + 방마다 다른 층고' 세 개를 꼭 써요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.06,0.9,0.1],"c":[0.005,0.01,0.99,0.2],"r":6.6,"img":"img/U3/walk/p047_22_01.jpg","say":"첫 문단. 라움플란은 space plan, 공간계획 이상의 의미예요."},{"b":[0.05,0.22,0.9,0.24],"c":[0.005,0.204,0.99,0.272],"r":4.8529,"img":"img/U3/walk/p047_22_02.jpg","say":"로스의 선언문. 시험에 그대로 나오는 문장이에요."},{"b":[0.34,0.44,0.62,0.51],"c":[0.309,0.4145,0.682,0.561],"r":1.6209,"img":"img/U3/walk/p047_22_03.jpg","say":"사진 두 장이 붙어 있어요. 왼쪽과 오른쪽이 다른 집이에요."},{"b":[0.34,0.46,0.3,0.47],"c":[0.325,0.4365,0.33,0.517],"r":0.8511,"img":"img/U3/walk/p047_22_04.jpg","say":"왼쪽은 **슈트라서 하우스**예요. 대리석 기둥과 소파가 보여요."},{"b":[0.65,0.46,0.3,0.47],"c":[0.635,0.4365,0.33,0.517],"r":0.8511,"img":"img/U3/walk/p047_22_05.jpg","say":"오른쪽은 **슈타이너 하우스**예요. 계단이 위로 이어져요."},{"b":[0.41,0.955,0.51,0.035],"c":[0.3845,0.8867,0.561,0.1133],"r":6.6019,"img":"img/U3/walk/p047_22_06.jpg","say":"캡션. 아돌프 로스, 스트라서 하우스(왼쪽)와 슈타이너 하우스(오른쪽)."}]}},{"p":48,"title":"아돌프 로스, 뮐러 하우스, 체코 프라하, 1930: 순수 형태 추구","terms":["뮐러 하우스","Adolf Loos","Raumplan"],"pass1":[{"kind":"say","lines":["**뮐러 하우스**는 **아돌프 로스(Adolf Loos)**의 1930년 작품이에요.","오스트리아 빈이 아니라 체코 프라하에 있어요.","**라움플란(Raumplan)**의 완성으로 평가되는 집이에요."]},{"kind":"analogy","head":"겉은 흰 상자, 속은 보석함","scene":"밖에서 보면 무늬 없는 흰 상자인데 열어 보면 대리석으로 가득해요.","map":[["흰 상자 같은 겉","순수 형태 추구"],["보석함 같은 속","풍부하게 장식된 내부"],["둘의 관계","극단적인 대비"]]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["**뮐러 하우스**의 외관은 풍부하게 장식된 내부와 극단적인 대비를 이뤄요.","순수 형태를 추구해요.","설계자 **아돌프 로스(Adolf Loos)**, 연도 1930년, 장소 체코 프라하예요."]},{"kind":"points","head":"이 쪽에서 볼 것","items":["왼쪽 사진 두 장은 바깥 모습이에요. 흰 벽에 네모 창만 뚫려 있어요.","창의 크기가 제각각이에요. 큰 창, 가로로 긴 창, 작은 네모 창이 섞여 있어요.","덩어리도 한 상자가 아니라 크기가 다른 상자들이 물려 있어요.","오른쪽은 층별 평면도 네 장이에요. Parterre, 1. Stock, 2. Stock, Dachgeschoss 라고 적혀 있어요.","각각 1층, 2층, 3층, 다락층이라는 뜻이에요. 방의 크기와 위치가 층마다 달라요.","층마다 다른 이 배치가 **라움플란(Raumplan)**의 결과예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**뮐러 하우스**가 위치한 도시는?","choices":["오스트리아 빈","체코 프라하","벨기에 브뤼셀"],"a":1,"why":"체코 프라하, 1930년이에요. 브뤼셀은 스토클레 저택이에요."},{"kind":"check","q":"**뮐러 하우스** 외관과 내부의 관계는?","choices":["외관과 내부 모두 무장식으로 통일돼요","외관은 풍부하게 장식된 내부와 극단적인 대비를 이뤄요","외관이 내부보다 화려해요"],"a":1,"why":"순수 형태의 외관과 풍부하게 장식된 내부가 극단적으로 대비돼요."}],"walk":{"head":null,"parts":[{"b":[0.66,0.05,0.12,0.04],"c":[0.62,0.015,0.2,0.11],"r":2.4242,"img":"img/U3/walk/p048_22_01.jpg","say":"제목. 뮐러하우스."},{"b":[0.47,0.12,0.51,0.1],"c":[0.439,0.104,0.561,0.132],"r":5.6667,"img":"img/U3/walk/p048_22_02.jpg","say":"두 항목. 외관과 내부의 극단적 대비, 순수 형태 추구."},{"b":[0.05,0.02,0.29,0.43],"c":[0.0355,0,0.319,0.473],"r":0.8992,"img":"img/U3/walk/p048_22_03.jpg","say":"바깥 모습. 흰 벽에 크기가 다른 네모 창이 뚫려 있어요."},{"b":[0.05,0.47,0.3,0.47],"c":[0.035,0.4465,0.33,0.517],"r":0.8511,"img":"img/U3/walk/p048_22_04.jpg","say":"다른 쪽 바깥 모습. 상자들이 서로 물려 있어요."},{"b":[0.48,0.26,0.5,0.72],"c":[0.45,0.208,0.55,0.792],"r":0.9259,"img":"img/U3/walk/p048_22_05.jpg","say":"층별 평면도 네 장. Parterre 부터 Dachgeschoss 까지예요."},{"b":[0.08,0.95,0.37,0.04],"c":[0.0615,0.89,0.407,0.11],"r":4.9333,"img":"img/U3/walk/p048_22_06.jpg","say":"캡션. 아돌프 로스, 뮐러 하우스, 체코 프라하, 1930."}]}},{"p":49,"title":"뮐러 하우스: 다양한 바닥 높이와 건축과 인테리어의 합치","terms":["뮐러 하우스","Raumplan","Adolf Loos"],"pass1":[{"kind":"say","lines":["이 쪽이 **뮐러 하우스**의 시험 포인트 네 가지예요.","다양한 바닥 높이, 층고에 구속되지 않는 공간계획,","분리되지 않는 하나로의 통합, 건축과 인테리어의 합치예요."]}],"pass2":[{"kind":"points","head":"슬라이드 글 그대로","items":["다양한 바닥 높이가 있어요.","층고에 구속되지 않는 모든 공간계획이에요.","각 공간을 분리되지 않는 하나로 통합하고 조화시켜요.","건축과 인테리어의 합치예요."]},{"kind":"points","head":"그림 세 장이 같은 말을 해요","items":["왼쪽 위는 단면도예요. 바닥을 나타내는 가로줄이 층마다 어긋나 있어요.","가운데에 계단이 짧게 여러 번 꺾이며 올라가요. 반 층씩 오르내린다는 뜻이에요.","왼쪽 아래는 실내 사진이에요. 계단이 거실 한가운데를 지나가요.","오른쪽은 투상도예요. 집을 비스듬히 잘라 방들을 위에서 내려다본 그림이에요.","방과 계단이 서로 다른 높이에서 맞물려 있는 것이 한눈에 보여요.","이것이 **라움플란(Raumplan)**의 모습이고, **뮐러 하우스**가 그 완성이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**라움플란(Raumplan)**의 완성으로 평가되는 주택은?","choices":["**슈타이너 하우스**","**슈트라서 하우스**","**뮐러 하우스**"],"a":2,"why":"뮐러 하우스(1930, 프라하)가 라움플란의 완성으로 평가돼요."},{"kind":"english","head":"논술 답안: 뮐러 하우스","en":"뮐러 하우스는 아돌프 로스가 1930년 체코 프라하에 설계한 주택으로, 순수 형태를 추구한 외관이 풍부하게 장식된 내부와 극단적인 대비를 이룬다.","ko":"다양한 바닥 높이와 층고에 구속되지 않는 공간계획으로 각 공간을 분리되지 않는 하나로 통합하고 조화시켜 건축과 인테리어의 합치를 이루었으며, 라움플란의 완성으로 평가된다.","tip":"'1930 + 프라하 + 순수 형태 + 바닥 높이 + 통합 + 라움플란 완성' 순서로 써요."}],"walk":{"head":null,"parts":[{"b":[0.08,0.02,0.4,0.32],"c":[0.06,0.004,0.44,0.352],"r":1.6667,"img":"img/U3/walk/p049_22_01.jpg","say":"단면도. 바닥을 나타내는 가로줄이 층마다 어긋나 있어요."},{"b":[0.28,0.04,0.18,0.26],"c":[0.268,0.024,0.204,0.292],"r":0.9315,"img":"img/U3/walk/p049_22_02.jpg","say":"계단 부분. 짧게 여러 번 꺾이며 올라가요."},{"b":[0.5,0.09,0.47,0.23],"c":[0.4765,0.074,0.517,0.262],"r":2.631,"img":"img/U3/walk/p049_22_03.jpg","say":"네 항목. 바닥 높이, 층고 자유, 통합, 건축과 인테리어의 합치."},{"b":[0.07,0.36,0.4,0.61],"c":[0.05,0.329,0.44,0.671],"r":0.8743,"img":"img/U3/walk/p049_22_04.jpg","say":"실내 사진. 계단이 거실 한가운데를 지나가요."},{"b":[0.55,0.34,0.38,0.6],"c":[0.531,0.31,0.418,0.66],"r":0.8444,"img":"img/U3/walk/p049_22_05.jpg","say":"투상도. 방들이 다른 높이에서 맞물려 있어요."},{"b":[0.55,0.945,0.38,0.035],"c":[0.531,0.89,0.418,0.11],"r":5.0667,"img":"img/U3/walk/p049_22_06.jpg","say":"캡션. 아돌프 로스, 뮐러 하우스, 체코 프라하, 1930."}]}},{"p":50,"title":"뮐러 하우스의 실내: 대리석과 나무로 짜인 서로 다른 높이의 방들","terms":["뮐러 하우스","Raumplan","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 세 장이에요. **뮐러 하우스**의 실내예요.","밖에서는 흰 상자였는데 안은 대리석과 나무로 가득해요.","바닥 높이가 서로 다른 방들이 난간 없이 이어져 있어요."]}],"pass2":[{"kind":"points","head":"이 사진들에서 볼 것","items":["왼쪽 위: 짙은 나무와 무늬 대리석으로 마감한 방이에요. 천장에는 반짝이는 나무판이 깔려 있어요.","바닥 높이가 다른 두 공간이 낮은 대리석 턱 하나로 나뉘어 있어요.","왼쪽 아래: 넓은 거실이에요. 초록빛 무늬 대리석 기둥과 벽이 보여요.","왼쪽 뒤로 계단 몇 단이 보여요. 옆방이 조금 높다는 뜻이에요.","오른쪽: 계단실이에요. 대리석 난간 너머로 아래 방이 내려다보여요.","천장은 짙은 나무판을 격자로 붙였고 둥근 조명이 매달려 있어요."]},{"kind":"points","head":"라움플란이 눈에 보이는 순간","items":["방과 방 사이에 벽 대신 높이 차이와 낮은 턱이 있어요.","그래서 한 방에서 옆방이 조금씩 보여요. 공간이 분리되지 않고 하나로 이어져요.","**아돌프 로스(Adolf Loos)**는 이것을 '변화가 지각되지 않고 자연스럽다'고 표현했어요.","**뮐러 하우스**는 겉의 무장식과 속의 값비싼 재료가 극단적으로 대비돼요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.03,0.48,0.43],"c":[0.006,0.0085,0.528,0.473],"r":1.4884,"img":"img/U3/walk/p050_22_01.jpg","say":"짙은 나무와 무늬 대리석의 방이에요."},{"b":[0.05,0.28,0.35,0.18],"c":[0.0325,0.264,0.385,0.212],"r":2.4214,"img":"img/U3/walk/p050_22_02.jpg","say":"낮은 대리석 턱. 여기서 바닥 높이가 달라져요."},{"b":[0.03,0.49,0.51,0.43],"c":[0.0045,0.4685,0.561,0.473],"r":1.5814,"img":"img/U3/walk/p050_22_03.jpg","say":"넓은 거실. 초록빛 무늬 대리석 기둥과 벽이에요."},{"b":[0.59,0.25,0.39,0.68],"c":[0.5705,0.216,0.429,0.748],"r":0.7647,"img":"img/U3/walk/p050_22_04.jpg","say":"계단실. 난간 너머로 아래 방이 내려다보여요."},{"b":[0.09,0.94,0.38,0.04],"c":[0.071,0.89,0.418,0.11],"r":5.0667,"img":"img/U3/walk/p050_22_05.jpg","say":"캡션. 아돌프 로스, 뮐러 하우스, 체코 프라하, 1930."}]}},{"p":51,"title":"무늬 대리석으로 짜인 홀 (캡션 없는 쪽)","terms":["뮐러 하우스","Raumplan"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. 글자 캡션은 없어요.","앞뒤 쪽과 같은 초록빛 무늬 대리석이 보여요.","**뮐러 하우스**의 홀을 넓게 찍은 사진으로 읽으면 돼요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것을 적어요","items":["이 쪽에는 캡션이 없어서 이름을 단정하지 않을게요. 보이는 것만 적어요.","벽과 기둥이 모두 초록빛 줄무늬 대리석이에요.","가운데에 허리 높이의 대리석 난간이 있고 그 너머가 한 단 낮아요.","난간 왼쪽에는 유리 상자 두 개가 벽에 끼워져 있어요.","오른쪽에는 몇 단짜리 계단과 한 단 높은 자리가 있어요.","천장에는 둥근 유리 조명 두 개가 매달려 있고 가운데에 둥근 천창이 있어요."]},{"kind":"points","head":"무엇을 봐야 할까요","items":["한 장면 안에 바닥 높이가 세 가지 이상 보여요.","그런데 벽으로 막은 곳이 없어서 전부 한 공간처럼 이어져요.","이것이 **라움플란(Raumplan)**이 만든 풍경이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.05,0.14,0.88,0.72],"c":[0.006,0.104,0.968,0.792],"r":1.6296,"img":"img/U3/walk/p051_22_01.jpg","say":"홀 전체. 초록빛 줄무늬 대리석이 벽과 기둥을 덮어요."},{"b":[0.13,0.48,0.35,0.22],"c":[0.1125,0.464,0.385,0.252],"r":2.037,"img":"img/U3/walk/p051_22_02.jpg","say":"허리 높이의 대리석 난간. 그 너머가 한 단 낮아요."},{"b":[0.47,0.38,0.2,0.25],"c":[0.458,0.364,0.224,0.282],"r":1.0591,"img":"img/U3/walk/p051_22_03.jpg","say":"가운데 뒤쪽. 계단 몇 단 위에 흉상이 놓여 있어요."},{"b":[0.66,0.5,0.28,0.25],"c":[0.646,0.484,0.308,0.282],"r":1.4563,"img":"img/U3/walk/p051_22_04.jpg","say":"오른쪽. 몇 단짜리 계단과 한 단 높은 자리예요."},{"b":[0.4,0.13,0.25,0.1],"c":[0.3875,0.114,0.275,0.132],"r":2.7778,"img":"img/U3/walk/p051_22_05.jpg","say":"천장 가운데의 둥근 천창이에요."}]}},{"p":52,"title":"라움플란으로써 각 공간은 어울리는 면적과 높이를 얻는다","terms":["Raumplan","뮐러 하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["이 쪽에는 **라움플란(Raumplan)**을 한 줄로 요약한 문장이 있어요.","'각 공간은 그 목적과 의미에 따라 각각에 어울리는 면적과 높이를 얻는다.'","**뮐러 하우스** 실내 사진 세 장이 그 증거예요."]}],"pass2":[{"kind":"points","head":"인용문을 풀어 읽어요","items":["'목적과 의미'는 그 방이 무엇을 하는 방인가를 말해요.","거실은 여럿이 모이니 넓고 높게, 서재는 혼자 쓰니 좁고 낮게 해요.","그래서 방마다 면적도 다르고 천장 높이도 달라져요.","이것이 **라움플란(Raumplan)**의 한 문장 정의예요."]},{"kind":"points","head":"이 사진들에서 볼 것","items":["위 왼쪽: 계단참이에요. 초록색 계단과 나무 난간, 천장에 노란 유리 천창이 있어요.","아래 왼쪽: 식당이에요. 둥근 나무 식탁과 의자, 위쪽에 반짝이는 나무 천장이에요.","식탁 뒤로 대리석 벽과 초록 커튼, 그리고 한 단 높은 자리가 보여요.","오른쪽: 작은 방이에요. 붉은 나무 책장이 계단처럼 층층이 짜여 있어요.","바닥은 초록색이고 몇 단 올라가면 다른 자리가 나와요.","세 장 모두 한 화면 안에 높이가 다른 바닥이 들어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'각 공간은 그 목적과 의미에 따라 각각에 어울리는 면적과 높이를 얻는다'는 무엇에 대한 설명일까요?","choices":["**총체예술(Total Art)**","**라움플란(Raumplan)**","**라움쿤스트(Raumkunst)**"],"a":1,"why":"라움플란을 한 문장으로 요약한 말이에요."}],"walk":{"head":null,"parts":[{"b":[0.28,0.03,0.32,0.48],"c":[0.264,0.006,0.352,0.528],"r":0.8889,"img":"img/U3/walk/p052_22_01.jpg","say":"계단참. 초록 계단과 노란 유리 천창이에요."},{"b":[0.09,0.52,0.48,0.44],"c":[0.066,0.498,0.528,0.484],"r":1.4545,"img":"img/U3/walk/p052_22_02.jpg","say":"식당. 둥근 나무 식탁과 반짝이는 나무 천장이에요."},{"b":[0.6,0.03,0.38,0.63],"c":[0.581,0,0.418,0.693],"r":0.8042,"img":"img/U3/walk/p052_22_03.jpg","say":"작은 방. 붉은 나무 책장이 층층이 짜여 있어요."},{"b":[0.62,0.3,0.28,0.3],"c":[0.606,0.284,0.308,0.332],"r":1.2369,"img":"img/U3/walk/p052_22_04.jpg","say":"바닥이 몇 단 올라가는 부분이에요."},{"b":[0.61,0.76,0.36,0.16],"c":[0.592,0.744,0.396,0.192],"r":2.75,"img":"img/U3/walk/p052_22_05.jpg","say":"인용문. 각 공간은 어울리는 면적과 높이를 얻는다."}]}},{"p":53,"title":"속을 잘라 보여 주는 주택 모형 (캡션 없는 쪽)","terms":["Raumplan","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 네 장이에요. 글자 캡션은 없어요.","나무로 만든 주택 모형을 유리장 안에서 찍은 사진들이에요.","속을 잘라서 방과 계단이 보이게 만든 모형이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만 적어요","items":["이 쪽에는 캡션이 없어서 어느 집인지 이름이 적혀 있지 않아요.","왼쪽 위: 모형의 바깥면이에요. 창이 크기가 제각각이고 벽이 계단처럼 층져 있어요.","오른쪽 위: 한쪽 벽을 떼어 낸 모습이에요. 천장이 높은 방과 낮은 방이 함께 보여요.","왼쪽 아래: 집 전체를 반으로 자른 모습이에요. 층마다 바닥 높이가 어긋나 있어요.","오른쪽 아래: 계단 부분이에요. 짧은 계단이 반 층씩 오르내려요.","모형이라서 벽 안쪽의 높이 차이를 눈으로 셀 수 있어요."]},{"kind":"points","head":"왜 모형으로 보여 줄까요","items":["**라움플란(Raumplan)**은 평면도 한 장으로는 이해가 잘 안 돼요.","방마다 높이가 다르니까 잘라서 봐야 알 수 있어요.","**아돌프 로스(Adolf Loos)**가 '나는 평면이 아니라 공간을 설계한다'고 한 이유가 여기 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.03,0.07,0.37,0.46],"c":[0.0115,0.047,0.407,0.506],"r":1.0725,"img":"img/U3/walk/p053_22_01.jpg","say":"모형의 바깥면. 창 크기가 제각각이에요."},{"b":[0.42,0.07,0.55,0.4],"c":[0.3925,0.05,0.605,0.44],"r":1.8333,"img":"img/U3/walk/p053_22_02.jpg","say":"한쪽 벽을 떼어 낸 모습. 높은 방과 낮은 방이 함께 보여요."},{"b":[0.03,0.54,0.37,0.43],"c":[0.0115,0.5185,0.407,0.473],"r":1.1473,"img":"img/U3/walk/p053_22_03.jpg","say":"반으로 자른 모습. 층마다 바닥 높이가 어긋나 있어요."},{"b":[0.42,0.55,0.55,0.42],"c":[0.3925,0.529,0.605,0.462],"r":1.746,"img":"img/U3/walk/p053_22_04.jpg","say":"계단 부분. 짧은 계단이 반 층씩 오르내려요."}]}},{"p":54,"title":"라움플란의 적용기법: 거실을 두 개 층으로 개방, 스플릿 레벨","terms":["Raumplan","split level","Adolf Loos"],"pass1":[{"kind":"say","lines":["이 쪽이 **라움플란(Raumplan)**을 실제로 쓰는 방법이에요.","첫째, 거실을 두 개 층으로 개방해요.","둘째, **스플릿 레벨(split level)**로 층고를 조절해요."]},{"kind":"analogy","head":"거실만 천장을 뚫기","scene":"카페에서 가운데만 이층까지 뻥 뚫려 있고 나머지는 낮은 것과 같아요.","map":[["뻥 뚫린 가운데","두 개 층으로 개방한 거실"],["낮은 나머지 자리","보통 층고의 방들"],["반 층 오르는 자리","**스플릿 레벨(split level)**"]]}],"pass2":[{"kind":"points","head":"이 쪽 용어 풀이","items":["**스플릿 레벨(split level)**: 한 층 안에서 바닥 높이를 반 층씩 어긋나게 두는 방식이에요.","**라움플란(Raumplan)**에서 층고를 조절할 때 가장 많이 쓰는 기법이에요.","단차는 바닥 높이의 차이, 동선은 사람이 움직이는 길을 말해요."]},{"kind":"points","head":"슬라이드 글 그대로","items":["거실을 두 개 층으로 개방하여 밝고 공간감 있는 거실을 확보해요.","단순한 실 배치이지만 거실을 높이고 개방함으로써 공간적 긴장감과 동선의 변화감을 유발해요.","즉 평면을 계획할 때 평면뿐만 아니라 볼륨의 면적 배분에 주안점을 두어 층고를 조절해요.","가장 많이 사용되는 기법은 **스플릿 레벨(split level)**을 이용한 층고의 조절이에요.","예를 들어 거실 주변으로 단차를 둬요."]},{"kind":"points","head":"아래 평면도 세 장을 읽어요","items":["왼쪽 평면도에 KUCHE(부엌), WOHNRAUM(거실), TERRASSE(테라스)라고 적혀 있어요.","가운데 평면도에는 ZWISCHENGESCHOSS, 즉 중간층이라고 적혀 있어요.","그 중간층에 GALERIE 라고 적힌 자리가 있어요. 거실 위를 내려다보는 자리예요.","거실 자리가 가운데 평면도에서 비어 있어요. 거실이 두 개 층으로 뚫려 있다는 뜻이에요.","오른쪽 평면도는 1. STOCK, 즉 그 위층이고 SCHLAFRAUM(침실)이 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**라움플란(Raumplan)**에서 가장 많이 사용되는 층고 조절 기법은?","choices":["**스플릿 레벨(split level)**","커튼월","필로티"],"a":0,"why":"스플릿 레벨로 층고를 조절해요. 예를 들어 거실 주변으로 단차를 둬요."},{"kind":"check","q":"**라움플란(Raumplan)**에서 거실을 두 개 층으로 개방하는 효과는?","choices":["재료를 아낄 수 있어요","밝고 공간감 있는 거실을 확보하고 공간적 긴장감과 동선의 변화감을 유발해요","냉난방이 잘돼요"],"a":1,"why":"밝고 공간감 있는 거실, 공간적 긴장감, 동선의 변화감이에요."},{"kind":"english","head":"논술 답안: 라움플란의 적용기법","en":"라움플란의 적용기법으로는 거실을 두 개 층으로 개방하여 밝고 공간감 있는 거실을 확보하는 방식이 있으며, 이를 통해 공간적 긴장감과 동선의 변화감을 유발한다.","ko":"평면뿐 아니라 볼륨의 면적 배분에 주안점을 두어 층고를 조절하며, 가장 많이 사용되는 기법은 스플릿 레벨을 이용한 층고의 조절로 거실 주변에 단차를 둔다.","tip":"'거실 두 개 층 개방 + 긴장감과 동선 + 볼륨 배분 + 스플릿 레벨' 네 개예요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.07,0.24,0.05],"c":[0.048,0.04,0.264,0.11],"r":3.2,"img":"img/U3/walk/p054_23_01.jpg","say":"제목. 라움플란의 적용기법."},{"b":[0.09,0.15,0.85,0.33],"c":[0.0475,0.1335,0.935,0.363],"r":3.4343,"img":"img/U3/walk/p054_23_02.jpg","say":"세 항목. 거실 두 개 층 개방, 볼륨 배분, 스플릿 레벨."},{"b":[0.16,0.53,0.24,0.42],"c":[0.148,0.509,0.264,0.462],"r":0.7619,"img":"img/U3/walk/p054_23_03.jpg","say":"왼쪽 평면도. KUCHE, WOHNRAUM, TERRASSE 가 보여요."},{"b":[0.41,0.53,0.22,0.42],"c":[0.398,0.509,0.244,0.462],"r":0.7042,"img":"img/U3/walk/p054_23_04.jpg","say":"가운데 평면도. ZWISCHENGESCHOSS 와 GALERIE 가 보여요."},{"b":[0.65,0.53,0.22,0.42],"c":[0.638,0.509,0.244,0.462],"r":0.7042,"img":"img/U3/walk/p054_23_05.jpg","say":"오른쪽 평면도. 1. STOCK 과 SCHLAFRAUM 이 보여요."}]}},{"p":55,"title":"루드비히 비트겐슈타인, 비트겐슈타인 하우스, 오스트리아 빈, 1929","terms":["비트겐슈타인 하우스","Adolf Loos"],"pass1":[{"kind":"say","lines":["사진 한 장이에요. **비트겐슈타인 하우스**예요.","철학자 루드비히 비트겐슈타인이 1929년 오스트리아 빈에 지었어요.","**아돌프 로스(Adolf Loos)**가 지은 집이 아니에요. 주의해요."]}],"pass2":[{"kind":"points","head":"이 사진에서 볼 것","items":["캡션은 루드비히 비트겐슈타인, **비트겐슈타인 하우스**, 오스트리아 빈, 1929예요.","지은 사람이 건축가가 아니라 철학자라는 점이 시험 포인트예요.","벽은 흰색 한 가지이고 무늬가 하나도 없어요.","창은 세로로 긴 네모이고 테두리 장식이 전혀 없어요.","덩어리가 크기가 다른 흰 상자 두세 개로 나뉘어 물려 있어요.","지붕은 평평하고 처마가 없어요."]},{"kind":"look","walked":1},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**비트겐슈타인 하우스**를 로스가 설계했다고 하면 틀려요.","철학자 루드비히 비트겐슈타인이 직접 지은 집이에요.","1929년, 오스트리아 빈이에요."]}],"pass3":[{"kind":"check","q":"**비트겐슈타인 하우스**를 지은 인물은?","choices":["아돌프 로스","루드비히 비트겐슈타인","요제프 호프만"],"a":1,"why":"철학자 루드비히 비트겐슈타인이 직접 지었어요. 1929년 빈이에요."},{"kind":"check","q":"1929년 빈에 자신의 집을 지은 철학자는?","choices":["루드비히 비트겐슈타인","아르투어 쇼펜하우어","칼 쇼르스케"],"a":0,"why":"루드비히 비트겐슈타인이에요."}],"walk":{"head":null,"parts":[{"b":[0.13,0.03,0.74,0.89],"c":[0.093,0,0.814,0.979],"r":1.1086,"img":"img/U3/walk/p055_21_01.jpg","say":"사진 전체. 비트겐슈타인 하우스의 정원 쪽이에요."},{"b":[0.19,0.1,0.56,0.55],"c":[0.162,0.0725,0.616,0.605],"r":1.3576,"img":"img/U3/walk/p055_21_02.jpg","say":"흰 상자 덩어리들. 크기가 다른 상자가 물려 있어요."},{"b":[0.2,0.24,0.22,0.25],"c":[0.188,0.224,0.244,0.282],"r":1.1537,"img":"img/U3/walk/p055_21_03.jpg","say":"창. 세로로 긴 네모이고 테두리 장식이 없어요."},{"b":[0.63,0.3,0.15,0.25],"c":[0.605,0.284,0.2,0.282],"r":0.9456,"img":"img/U3/walk/p055_21_04.jpg","say":"오른쪽 낮은 덩어리. 지붕이 평평하고 처마가 없어요."},{"b":[0.19,0.955,0.52,0.035],"c":[0.164,0.8844,0.572,0.1156],"r":6.5975,"img":"img/U3/walk/p055_21_05.jpg","say":"캡션. 루드비히 비트겐슈타인, 비트겐슈타인하우스, 빈, 1929."}]}},{"p":56,"title":"비트겐슈타인 하우스의 모형과 명판 (캡션 없는 쪽)","terms":["비트겐슈타인 하우스"],"pass1":[{"kind":"say","lines":["사진 두 장이에요. 글자 캡션은 없어요.","왼쪽 아래 돌판에 HAUS WITTGENSTEIN 이라고 새겨져 있어요.","앞 쪽에서 본 **비트겐슈타인 하우스**의 모형과 명판이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것을 적어요","items":["오른쪽: 나무로 만든 집 모형이에요. 크기가 다른 네모 덩어리들이 물려 있어요.","창은 벽에 홈처럼 파여 있고 장식 테두리가 없어요.","지붕은 모두 평평하고 난간이 낮게 둘러져 있어요.","왼쪽 아래: 돌 명판이에요. HAUS WITTGENSTEIN 이라는 제목이 크게 새겨져 있어요.","그 아래 작은 글씨에 LUDWIG WITTGENSTEIN(1889-1951)과 PAUL ENGELMANN(1891-1965), 그리고 1929 가 보여요.","즉 이 집이 1929년에 완성되었다는 사실이 돌판에 남아 있어요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.22,0.02,0.76,0.56],"c":[0.164,0,0.836,0.616],"r":1.8095,"img":"img/U3/walk/p056_21_01.jpg","say":"나무 모형. 크기가 다른 네모 덩어리들이 물려 있어요."},{"b":[0.53,0.38,0.3,0.18],"c":[0.515,0.364,0.33,0.212],"r":2.0755,"img":"img/U3/walk/p056_21_02.jpg","say":"모형의 창. 벽에 홈처럼 파여 있고 테두리 장식이 없어요."},{"b":[0.01,0.61,0.38,0.37],"c":[0,0.5915,0.418,0.407],"r":1.3694,"img":"img/U3/walk/p056_21_03.jpg","say":"돌 명판. HAUS WITTGENSTEIN 이라고 새겨져 있어요."},{"b":[0.05,0.72,0.3,0.12],"c":[0.035,0.704,0.33,0.152],"r":2.8947,"img":"img/U3/walk/p056_21_04.jpg","say":"작은 글씨. 비트겐슈타인의 생몰년과 1929 가 보여요."}]}},{"p":57,"title":"비트겐슈타인 하우스의 두 모습, 그리고 3강 마무리","terms":["비트겐슈타인 하우스","Adolf Loos","Raumplan","Otto Wagner","요제프 호프만","Total Art"],"pass1":[{"kind":"say","lines":["3강의 마지막 쪽이에요. 사진 두 장뿐이고 글자 캡션은 없어요.","앞 쪽과 같은 흰 건물, **비트겐슈타인 하우스**의 바깥 모습이에요.","여기까지가 빈 분리파와 근대건축의 태동이에요."]},{"kind":"recap","items":["3강을 한 번에 정리해요.","**요제프 호프만**은 **총체예술(Total Art)**로 건물부터 가구까지 다 디자인했어요.","**오토 바그너(Otto Wagner)**는 필요만이 예술의 주인이라며 장식을 정리했어요.","**아돌프 로스(Adolf Loos)**는 장식을 죄악이라 하고 **라움플란(Raumplan)**으로 공간을 설계했어요.","주문을 마지막으로 외워요. 싫어 → 새 장식 → 정리 → 없애."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것을 적어요","items":["두 장 모두 흰 벽에 세로로 긴 창이 규칙적으로 뚫린 건물이에요.","위 사진: 위에서 비스듬히 본 모습이에요. 높이가 다른 흰 상자들이 물려 있어요.","아래 사진: 현관 쪽이에요. 나무 문 위에 둥근 등이 하나 달려 있어요.","장식이라고 부를 만한 것이 하나도 없어요.","**비트겐슈타인 하우스**는 1929년 빈에 지어졌어요."]},{"kind":"points","head":"3강 인물과 대표작 총정리","items":["**요제프 호프만**: 푸커스도르프 요양원(1905), 스토클레 저택(1911, 브뤼셀).","올브리히: 분리파 전시관(1898, 빈). 클림트 주도, 지하에 베토벤 프리즈.","**오토 바그너(Otto Wagner)**: 앙커하우스(1895), 마욜리카하우스와 링케 빈 차일레(1898), 칼스플라츠 역사(1901), 우편저축은행(1906), 노이슈티프트가세(1911).","**아돌프 로스(Adolf Loos)**: 아메리칸 바(1908), 슈타이너(1910), 로스하우스(1912), 슈트라서(1918), 뮐러 하우스(1930, 프라하).","루드비히 비트겐슈타인: **비트겐슈타인 하우스**(1929, 빈)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**아돌프 로스(Adolf Loos)**의 주택 작품을 연도 순서로 바르게 늘어놓은 것은?","choices":["슈타이너(1910) → 슈트라서(1918) → 뮐러(1930)","뮐러(1910) → 슈타이너(1918) → 슈트라서(1930)","슈트라서(1910) → 뮐러(1918) → 슈타이너(1930)"],"a":0,"why":"슈타이너 1910 빈, 슈트라서 1918 빈, 뮐러 1930 프라하예요."},{"kind":"warn","head":"3강에서 가장 많이 틀리는 것들","items":["스토클레 저택은 브뤼셀, **비트겐슈타인 하우스**는 빈, 뮐러 하우스는 프라하예요.","분리파 결성 1897, 분리파 전시관 1898을 한 해 차이로 구분해요.","**비트겐슈타인 하우스**는 **아돌프 로스(Adolf Loos)**의 작품이 아니에요."]},{"kind":"english","head":"논술 답안: 호프만과 로스의 대비","en":"요제프 호프만은 총체예술을 주장하여 건축에서 가구까지 모든 것을 하나의 작품으로 통합하였고 대량생산에 반대하여 장인적 기술과 값비싼 재료를 사용하였다.","ko":"반면 아돌프 로스는 장식과 죄악에서 장식을 근대문명에서 제거해야 할 타락으로 보고 제체시온의 심미적 경향을 비판하였으며, 무장식 외관과 라움플란의 공간 구성을 보여 주었다.","tip":"'호프만은 통합, 로스는 제거'로 대비해서 외워요."}],"walk":{"head":null,"parts":[{"b":[0.13,0.01,0.85,0.55],"c":[0.065,0,0.935,0.605],"r":2.0606,"img":"img/U3/walk/p057_22_01.jpg","say":"위 사진. 높이가 다른 흰 상자들이 물려 있어요."},{"b":[0.6,0.15,0.25,0.3],"c":[0.5875,0.134,0.275,0.332],"r":1.1044,"img":"img/U3/walk/p057_22_02.jpg","say":"세로로 긴 창들. 테두리 장식이 없어요."},{"b":[0.02,0.43,0.58,0.55],"c":[0,0.395,0.638,0.605],"r":1.4061,"img":"img/U3/walk/p057_22_03.jpg","say":"아래 사진. 현관 쪽이에요."},{"b":[0.2,0.78,0.15,0.2],"c":[0.175,0.764,0.2,0.232],"r":1.1494,"img":"img/U3/walk/p057_22_04.jpg","say":"나무 문과 그 위의 둥근 등이에요."}]}}]};
